import React from 'react';
import LiveInteractiveGame from '../../pages/interactive-learning-session/components/LiveInteractiveGame';
import StyledGameShell from './StyledGameShell';

/**
 * Single entry for legacy + styled games (canvas, session, catalog).
 */
const GameRenderer = ({ game, uiAdaptations, onComplete, onAbandon, disabled }) => {
  if (!game) return null;

  if (game.engine === 'styled' || game.style_id || game.payload?.style_id) {
    return (
      <StyledGameShell
        game={game}
        uiAdaptations={uiAdaptations}
        onComplete={onComplete}
        disabled={disabled}
      />
    );
  }

  return (
    <LiveInteractiveGame
      game={game}
      uiAdaptations={uiAdaptations}
      onComplete={onComplete}
      onAbandon={onAbandon}
    />
  );
};

export default GameRenderer;
