import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Icon from '../AppIcon';

const AdaptiveProgressIndicator = ({ 
  currentProgress = 65, 
  weeklyStreak = 7, 
  completedSessions = 12,
  totalSessions = 20,
  learningMode = 'adaptive' // 'adaptive', 'collaborative', 'ar'
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [animatedProgress, setAnimatedProgress] = useState(0);
  const location = useLocation();

  // Animate progress on mount
  useEffect(() => {
    const timer = setTimeout(() => {
      setAnimatedProgress(currentProgress);
    }, 300);
    return () => clearTimeout(timer);
  }, [currentProgress]);

  const getContextualInfo = () => {
    switch (location.pathname) {
      case '/adaptive-learning-dashboard':
        return {
          title: 'Learning Path Progress',
          subtitle: 'Adaptive AI recommendations',
          icon: 'Brain',
          color: 'primary'
        };
      case '/interactive-learning-session':
        return {
          title: 'Session Progress',
          subtitle: 'Current learning session',
          icon: 'Play',
          color: 'secondary'
        };
      case '/progress-analytics-dashboard':
        return {
          title: 'Overall Progress',
          subtitle: 'Complete learning analytics',
          icon: 'TrendingUp',
          color: 'success'
        };
      case '/user-profile-settings':
        return {
          title: 'Profile Completion',
          subtitle: 'Personalization settings',
          icon: 'User',
          color: 'accent'
        };
      default:
        return {
          title: 'Learning Progress',
          subtitle: 'Your learning journey',
          icon: 'Target',
          color: 'primary'
        };
    }
  };

  const contextInfo = getContextualInfo();
  const progressPercentage = (animatedProgress / 100) * 283; // 283 is circumference of circle with radius 45
  const sessionProgress = (completedSessions / totalSessions) * 100;

  const getModeIcon = () => {
    switch (learningMode) {
      case 'collaborative':
        return 'Users';
      case 'ar':
        return 'Glasses';
      default:
        return 'Zap';
    }
  };

  const getModeColor = () => {
    switch (learningMode) {
      case 'collaborative':
        return 'text-secondary';
      case 'ar':
        return 'text-accent';
      default:
        return 'text-primary';
    }
  };

  return (
    <div className="fixed top-20 right-4 z-40 lg:top-24 lg:right-6">
      <div 
        className={`bg-surface border border-border rounded-xl shadow-warm-md transition-all duration-300 ${
          isExpanded ? 'w-80 p-4' : 'w-16 h-16 p-2'
        }`}
        onMouseEnter={() => setIsExpanded(true)}
        onMouseLeave={() => setIsExpanded(false)}
      >
        {!isExpanded ? (
          // Collapsed State - Progress Ring Only
          <div className="relative w-12 h-12">
            <svg className="w-12 h-12 transform -rotate-90" viewBox="0 0 100 100">
              {/* Background Circle */}
              <circle
                cx="50"
                cy="50"
                r="45"
                stroke="currentColor"
                strokeWidth="8"
                fill="none"
                className="text-surface-100"
              />
              {/* Progress Circle */}
              <circle
                cx="50"
                cy="50"
                r="45"
                stroke="currentColor"
                strokeWidth="8"
                fill="none"
                strokeDasharray="283"
                strokeDashoffset={283 - progressPercentage}
                className={`text-${contextInfo.color} transition-all duration-1000 ease-out`}
                strokeLinecap="round"
              />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center">
              <Icon 
                name={contextInfo.icon} 
                size={16} 
                className={`text-${contextInfo.color}`}
              />
            </div>
          </div>
        ) : (
          // Expanded State - Full Progress Dashboard
          <div className="animate-fade-in">
            {/* Header */}
            <div className="flex items-center justify-between mb-4">
              <div>
                <h3 className="font-heading font-semibold text-text-primary text-sm">
                  {contextInfo.title}
                </h3>
                <p className="text-xs text-text-secondary font-caption">
                  {contextInfo.subtitle}
                </p>
              </div>
              <div className={`p-2 rounded-lg bg-${contextInfo.color}-50`}>
                <Icon 
                  name={contextInfo.icon} 
                  size={16} 
                  className={`text-${contextInfo.color}`}
                />
              </div>
            </div>

            {/* Main Progress Ring */}
            <div className="flex items-center space-x-4 mb-4">
              <div className="relative w-16 h-16">
                <svg className="w-16 h-16 transform -rotate-90" viewBox="0 0 100 100">
                  <circle
                    cx="50"
                    cy="50"
                    r="45"
                    stroke="currentColor"
                    strokeWidth="6"
                    fill="none"
                    className="text-surface-100"
                  />
                  <circle
                    cx="50"
                    cy="50"
                    r="45"
                    stroke="currentColor"
                    strokeWidth="6"
                    fill="none"
                    strokeDasharray="283"
                    strokeDashoffset={283 - progressPercentage}
                    className={`text-${contextInfo.color} transition-all duration-1000 ease-out`}
                    strokeLinecap="round"
                  />
                </svg>
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="text-lg font-heading font-semibold text-text-primary">
                    {Math.round(animatedProgress)}%
                  </span>
                </div>
              </div>

              <div className="flex-1">
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-text-secondary font-caption">Sessions</span>
                    <span className="text-text-primary font-medium">
                      {completedSessions}/{totalSessions}
                    </span>
                  </div>
                  <div className="w-full bg-surface-100 rounded-full h-2">
                    <div 
                      className={`bg-${contextInfo.color} h-2 rounded-full transition-all duration-1000 ease-out`}
                      style={{ width: `${sessionProgress}%` }}
                    ></div>
                  </div>
                </div>
              </div>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-2 gap-3 mb-4">
              <div className="bg-surface-50 rounded-lg p-3">
                <div className="flex items-center space-x-2">
                  <Icon name="Flame" size={14} className="text-accent" />
                  <span className="text-xs font-caption text-text-secondary">Streak</span>
                </div>
                <p className="text-lg font-heading font-semibold text-text-primary mt-1">
                  {weeklyStreak}
                </p>
                <p className="text-xs text-text-secondary">days</p>
              </div>

              <div className="bg-surface-50 rounded-lg p-3">
                <div className="flex items-center space-x-2">
                  <Icon name="Clock" size={14} className="text-secondary" />
                  <span className="text-xs font-caption text-text-secondary">Today</span>
                </div>
                <p className="text-lg font-heading font-semibold text-text-primary mt-1">
                  2.5h
                </p>
                <p className="text-xs text-text-secondary">learned</p>
              </div>
            </div>

            {/* Learning Mode Indicator */}
            <div className="flex items-center justify-between p-2 bg-surface-50 rounded-lg">
              <div className="flex items-center space-x-2">
                <Icon 
                  name={getModeIcon()} 
                  size={14} 
                  className={getModeColor()}
                />
                <span className="text-xs font-caption text-text-secondary">
                  {learningMode === 'collaborative' ? 'Collaborative Mode' : 
                   learningMode === 'ar' ? 'AR Mode' : 'Adaptive Mode'}
                </span>
              </div>
              <div className={`w-2 h-2 rounded-full ${
                learningMode === 'collaborative' ? 'bg-secondary' :
                learningMode === 'ar' ? 'bg-accent' : 'bg-primary'
              } animate-pulse`}></div>
            </div>

            {/* Quick Actions */}
            <div className="flex space-x-2 mt-3">
              <button className="flex-1 bg-primary text-white text-xs font-medium py-2 px-3 rounded-lg hover:bg-primary-700 transition-colors duration-200 active:transform active:translate-y-px">
                Continue Learning
              </button>
              <button className="p-2 border border-border rounded-lg hover:bg-surface-50 transition-colors duration-200">
                <Icon name="MoreHorizontal" size={14} className="text-text-secondary" />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdaptiveProgressIndicator;