import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { UserContext } from './UserContext';
import api from '../lib/api';

export const GoalsContext = createContext(null);

export const GoalsProvider = ({ children }) => {
  const { currentUser } = useContext(UserContext);
  const [goals, setGoals] = useState([]);
  const [loading, setLoading] = useState(false);

  const refresh = useCallback(async () => {
    if (!currentUser?.uid) return;
    try {
      setLoading(true);
      const data = await api.getGoals();
      setGoals(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error('Failed to load goals:', err);
    } finally {
      setLoading(false);
    }
  }, [currentUser?.uid]);

  const createGoal = async (payload) => {
    const goal = await api.createGoal(payload);
    await refresh();
    return goal;
  };

  const updateGoal = async (goalId, payload) => {
    const updated = await api.updateGoal(goalId, payload);
    await refresh();
    return updated;
  };

  const deleteGoal = async (goalId) => {
    await api.deleteGoal(goalId);
    await refresh();
  };

  useEffect(() => {
    refresh();
  }, [refresh]);

  const activeGoals = goals.filter((g) => g.status === 'active');
  const completedGoals = goals.filter((g) => g.status === 'completed');

  return (
    <GoalsContext.Provider
      value={{ goals, activeGoals, completedGoals, loading, refresh, createGoal, updateGoal, deleteGoal }}
    >
      {children}
    </GoalsContext.Provider>
  );
};

export function useGoals() {
  return useContext(GoalsContext) || {};
}
