/**
 * Robust SSE frame parser — keeps event type across chunk boundaries.
 */

export async function readSseStream(reader, handlers = {}) {
  if (!reader) throw new Error('Response body is not readable');

  const decoder = new TextDecoder();
  let buf = '';
  let currentEvent = '';
  let finalResult = null;
  let streamError = null;

  const dispatch = (event, data) => {
    if (event === 'coach' && handlers.onCoach) handlers.onCoach(data);
    else if (event === 'surface' && handlers.onSurface) handlers.onSurface(data);
    else if (event === 'surface_ready' && handlers.onSurfaceReady) handlers.onSurfaceReady(data);
    else if (event === 'done') {
      finalResult = data;
      if (handlers.onDone) handlers.onDone(data);
    } else if (event === 'error') {
      streamError = new Error(data?.error || 'Stream failed');
      if (handlers.onError) handlers.onError(data);
    }
  };

  const processLines = (lines) => {
    for (const line of lines) {
      if (line === '') {
        currentEvent = '';
        continue;
      }
      if (line.startsWith('event: ')) {
        currentEvent = line.slice(7).trim();
        continue;
      }
      if (!line.startsWith('data: ')) continue;

      const raw = line.slice(6);
      if (raw === '[DONE]') continue;

      try {
        const data = JSON.parse(raw);
        dispatch(currentEvent, data);
      } catch {
        /* partial JSON — wait for more chunks */
      }
    }
  };

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += decoder.decode(value, { stream: true });
    const lines = buf.split('\n');
    buf = lines.pop() || '';
    processLines(lines);
  }

  if (buf.trim()) {
    processLines(buf.split('\n'));
  }

  if (streamError) throw streamError;
  return finalResult;
}
