import React, { createContext, useState, useEffect, useContext } from 'react';
import { UserContext } from './UserContext';
import api from '../lib/api';

export const AIContext = createContext(null);

const AI_SETTINGS_STORAGE_KEY = 'adaptiveLearnAISettings_guest';

const initialAISettings = {
  adaptiveLearningEnabled: true,
  personalizedContent: true,
  difficultyAdjustment: 'automatic',
  learningStyle: 'visual',
  responseTime: 'normal',
  contentTheme: 'default',
  useLocalLlm: false,
  localLlmModel: 'qwen2.5-coder:1.5b',
  gameEngine: 'styled',
};

export const AIProvider = ({ children }) => {
  const { currentUser } = useContext(UserContext) || {};
  const [aiSettings, setAISettings] = useState(initialAISettings);
  const [aiConfigured, setAiConfigured] = useState(false);
  const [aiStatus, setAiStatus] = useState(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [adaptiveMetrics, setAdaptiveMetrics] = useState({
    learningRate: 'medium', // slow, medium, fast
    strengths: [],
    weaknesses: [],
    preferredContentTypes: ['text', 'visual'],
    attentionSpan: 20, // minutes
    optimalSessionLength: 30, // minutes
  });

  // Load AI settings from VPS when authenticated, localStorage for guests
  useEffect(() => {
    const loadSettings = async () => {
      try {
        if (currentUser?.uid) {
          const [remote, status] = await Promise.all([api.getAISettings(), api.getAIStatus()]);
          setAISettings({ ...initialAISettings, ...remote });
          setAiStatus(status);
          setAiConfigured(Boolean(status?.configured));
          return;
        }
        setAiConfigured(false);

        const storedSettings = localStorage.getItem(AI_SETTINGS_STORAGE_KEY);
        if (storedSettings) {
          setAISettings({ ...initialAISettings, ...JSON.parse(storedSettings) });
        }
      } catch (error) {
        console.error('Error loading AI settings:', error);
      }
    };

    loadSettings();
  }, [currentUser?.uid]);

  // Save AI settings
  const updateAISettings = async (newSettings) => {
    const updatedSettings = { ...aiSettings, ...newSettings };
    setAISettings(updatedSettings);

    try {
      if (currentUser?.uid) {
        await api.updateAISettings(updatedSettings);
      } else {
        localStorage.setItem(AI_SETTINGS_STORAGE_KEY, JSON.stringify(updatedSettings));
      }
    } catch (error) {
      console.error('Error saving AI settings:', error);
    }
  };

  const generatePersonalizedContent = async (topic, contentType = 'lesson', options = {}) => {
    if (!currentUser?.uid || !aiConfigured) return null;

    setIsGenerating(true);
    try {
      const prompt = buildContentPrompt(topic, contentType, adaptiveMetrics, aiSettings, options);
      const result = await api.aiGenerate({
        topic,
        contentType,
        options: { ...options, prompt, metrics: adaptiveMetrics },
      });
      return result ? parseGeneratedContent(result.content || result, contentType) : result;
    } catch (error) {
      console.error('Error generating content:', error);
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  const generateProceduralModule = async (topic, options = {}) => {
    if (!currentUser?.uid || !aiConfigured) return null;

    setIsGenerating(true);
    try {
      const parsed = await api.aiModule({ topic, options: { ...options, metrics: adaptiveMetrics } });
      return normalizeProceduralModule(parsed, topic);
    } catch (error) {
      console.error('Error generating procedural module:', error);
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  const adaptLearning = (performanceData) => {
    const { accuracy, timeSpent, strugglingTopics, masteredTopics } = performanceData;

    let newLearningRate = adaptiveMetrics.learningRate;
    if (accuracy > 0.9 && timeSpent < adaptiveMetrics.optimalSessionLength) {
      newLearningRate = 'fast';
    } else if (accuracy < 0.6 || timeSpent > adaptiveMetrics.optimalSessionLength * 1.5) {
      newLearningRate = 'slow';
    } else {
      newLearningRate = 'medium';
    }

    setAdaptiveMetrics((prev) => ({
      ...prev,
      learningRate: newLearningRate,
      strengths: [...new Set([...prev.strengths, ...masteredTopics])],
      weaknesses: [...new Set([...prev.weaknesses, ...strugglingTopics])],
    }));

    const result = {
      suggestedDifficulty: newLearningRate === 'fast' ? 'increase' : newLearningRate === 'slow' ? 'decrease' : 'maintain',
      recommendedContentTypes: getRecommendedContentTypes(newLearningRate, aiSettings.learningStyle),
      suggestedBreakTime: newLearningRate === 'slow' ? 10 : 5,
      nextTopicSuggestions: generateNextTopics(masteredTopics, strugglingTopics),
    };

    if (currentUser?.uid) {
      api.analyzePerformance(performanceData).catch(() => {});
    }

    return result;
  };

  const generateAdaptiveQuiz = async (topic, difficulty, questionCount = 5) => {
    if (!currentUser?.uid || !aiConfigured) return null;
    setIsGenerating(true);
    try {
      return await api.aiQuiz({ topic, difficulty, questionCount });
    } catch (error) {
      console.error('Error generating quiz:', error);
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  const generateInteractiveGame = async (topic, context = {}) => {
    if (!currentUser?.uid) return null;
    setIsGenerating(true);
    try {
      if (aiSettings.useLocalLlm) {
        const { compileGameHybrid } = await import('../lib/gameCompilerClient');
        const result = await compileGameHybrid(topic, {
          preferLocal: true,
          lessonSnippet: context.lessonSnippet,
          styleId: context.gameType,
        });
        return result?.game || null;
      }
      if (!aiConfigured) return null;
      const result = await api.aiInteractiveGame({
        topic,
        context: {
          ...context,
          learningRate: adaptiveMetrics.learningRate,
          useLocalLlm: aiSettings.useLocalLlm,
        },
      });
      return result?.game || null;
    } catch (error) {
      console.error('Error generating interactive game:', error);
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  const adaptMidSession = async (topic, signals = {}) => {
    if (!currentUser?.uid || !aiConfigured) return null;
    setIsGenerating(true);
    try {
      const result = await api.aiSessionAdapt({ topic, signals });
      return result?.adaptation || null;
    } catch (error) {
      console.error('Error adapting session:', error);
      return null;
    } finally {
      setIsGenerating(false);
    }
  };

  // Get learning recommendations
  const getLearningRecommendations = () => {
    const recommendations = [];
    
    // Based on weaknesses
    if (adaptiveMetrics.weaknesses.length > 0) {
      recommendations.push({
        type: 'review',
        title: 'Review Challenging Topics',
        topics: adaptiveMetrics.weaknesses.slice(0, 3),
        priority: 'high'
      });
    }

    // Based on learning rate
    if (adaptiveMetrics.learningRate === 'fast') {
      recommendations.push({
        type: 'advance',
        title: 'Ready for Advanced Topics',
        suggestion: 'Consider moving to more challenging material',
        priority: 'medium'
      });
    } else if (adaptiveMetrics.learningRate === 'slow') {
      recommendations.push({
        type: 'reinforce',
        title: 'Strengthen Foundations',
        suggestion: 'Focus on fundamental concepts before advancing',
        priority: 'high'
      });
    }

    return recommendations;
  };

  const value = {
    aiSettings,
    updateAISettings,
    adaptiveMetrics,
    isGenerating,
    generatePersonalizedContent,
    adaptLearning,
    generateAdaptiveQuiz,
    generateProceduralModule,
    generateInteractiveGame,
    adaptMidSession,
    getLearningRecommendations,
    hasValidApiKey: aiConfigured,
    aiConfigured,
    aiStatus,
  };

  return (
    <AIContext.Provider value={value}>
      {children}
    </AIContext.Provider>
  );
};

// Helper functions
function buildContentPrompt(topic, contentType, metrics, settings, options) {
  if (options.prompt) {
    return options.prompt;
  }

  const basePrompt = `Generate ${contentType} content about "${topic}" for an adaptive learning application.
  
  User Profile:
  - Learning style: ${settings.learningStyle}
  - Learning rate: ${metrics.learningRate}
  - Attention span: ${metrics.attentionSpan} minutes
  - Preferred content: ${metrics.preferredContentTypes.join(', ')}
  - Content theme: ${settings.contentTheme}
  
  Strengths: ${metrics.strengths.join(', ') || 'None identified yet'}
  Weaknesses: ${metrics.weaknesses.join(', ') || 'None identified yet'}
  Additional guidance: ${options.focus || 'Keep content practical and engaging.'}`;

  switch (contentType) {
    case 'lesson':
      return `${basePrompt}
      
      Create an engaging lesson that includes:
      1. Clear introduction explaining why this topic matters
      2. Main content with examples relevant to the user's interests
      3. Interactive elements or practice problems
      4. Key takeaways
      5. Real-world applications
      
      Format: Use markdown for structure. Keep paragraphs short. Include examples and analogies.
      Length: Appropriate for ${metrics.attentionSpan} minute attention span.`;
      
    case 'explanation':
      return `${basePrompt}
      
      Provide a clear, step-by-step explanation that breaks down complex concepts into digestible parts.
      Use the ${settings.learningStyle} learning style approach.
      Include analogies and examples.`;
      
    case 'practice':
      return `${basePrompt}
      
      Create practice problems or exercises that reinforce learning.
      Include immediate feedback and hints.
      Difficulty should match ${metrics.learningRate} learning rate.`;
      
    default:
      return basePrompt;
  }
}

function buildProceduralModulePrompt(topic, metrics, settings, options) {
  const lessonCount = options.lessonCount || 4;
  const estimatedMinutes = options.estimatedMinutes || metrics.optimalSessionLength;

  return `You are generating a procedural learning module for an adaptive learning app.
Topic: "${topic}"
Learning style: ${settings.learningStyle}
Learning rate: ${metrics.learningRate}
Preferred content: ${metrics.preferredContentTypes.join(', ')}
Content theme: ${settings.contentTheme}
Target lessons: ${lessonCount}
Target session length: ${estimatedMinutes} minutes

Return ONLY valid JSON using this schema:
{
  "moduleTitle": "string",
  "overview": "string",
  "lessons": [
    {
      "title": "string",
      "objective": "string",
      "introduction": "string",
      "content": "string",
      "keyTakeaways": ["string"],
      "practiceProblems": [
        {
          "question": "string",
          "options": ["string"],
          "correct": 0,
          "explanation": "string"
        }
      ],
      "checkpoints": [
        {
          "question": "string",
          "expectedAnswer": "string",
          "rubric": "string"
        }
      ],
      "interactiveElements": ["string"],
      "estimatedMinutes": 10,
      "contentType": "concept"
    }
  ],
  "adaptiveRules": [
    {
      "trigger": "string",
      "adjustment": "string",
      "reason": "string"
    }
  ],
  "learningStyleHints": ["string"]
}

Ensure JSON is valid. Include at least 2 practice problems across the module.`;
}

function parseGeneratedContent(content, contentType) {
  if (typeof content === 'object') return content;
  const parsed = safeJsonParse(content);
  if (parsed) return parsed;

  return {
    type: contentType,
    content,
    generatedAt: new Date().toISOString(),
  };
}

function safeJsonParse(content) {
  if (!content) return null;
  try {
    const sanitized = stripJsonFences(content);
    return JSON.parse(sanitized);
  } catch (error) {
    console.warn('Unable to parse JSON content from AI:', error);
    return null;
  }
}

function stripJsonFences(content) {
  const trimmed = content.trim();
  if (trimmed.startsWith('```')) {
    return trimmed.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
  }
  return trimmed;
}

function normalizeProceduralModule(moduleData, topic) {
  if (!moduleData || !Array.isArray(moduleData.lessons)) {
    return null;
  }

  const moduleTitle = moduleData.moduleTitle || `${topic} Learning Module`;
  const lessons = moduleData.lessons.map((lesson, index) => ({
    id: lesson.id || `${slugify(topic)}-${index + 1}`,
    title: lesson.title || `Lesson ${index + 1}`,
    order: index + 1,
    type: lesson.contentType || 'concept',
    duration: lesson.estimatedMinutes ? `${lesson.estimatedMinutes} min` : '20 min',
    content: {
      introduction: lesson.introduction || lesson.objective || '',
      mainContent: lesson.content || '',
      keyTakeaways: Array.isArray(lesson.keyTakeaways) ? lesson.keyTakeaways : [],
      practiceProblems: normalizePracticeProblems(lesson.practiceProblems),
      interactiveElements: normalizeInteractiveElements(lesson.interactiveElements)
    },
    checkpoints: Array.isArray(lesson.checkpoints) ? lesson.checkpoints : []
  }));

  return {
    moduleTitle,
    overview: moduleData.overview || '',
    lessons,
    adaptiveRules: Array.isArray(moduleData.adaptiveRules) ? moduleData.adaptiveRules : [],
    learningStyleHints: Array.isArray(moduleData.learningStyleHints) ? moduleData.learningStyleHints : []
  };
}

function normalizePracticeProblems(practiceProblems) {
  if (!Array.isArray(practiceProblems)) return [];
  return practiceProblems.map((problem, index) => ({
    question: problem.question || `Practice question ${index + 1}`,
    options: Array.isArray(problem.options) && problem.options.length > 1 ? problem.options : ['Option A', 'Option B', 'Option C', 'Option D'],
    correct: Number.isInteger(problem.correct) ? problem.correct : 0,
    explanation: problem.explanation || 'Review the lesson content and try again.'
  }));
}

function normalizeInteractiveElements(elements) {
  if (!Array.isArray(elements)) return [];
  return elements.map((element) => ({
    type: 'activity',
    label: element,
    action: slugify(element)
  }));
}

function slugify(value = '') {
  return value
    .toString()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function getRecommendedContentTypes(learningRate, learningStyle) {
  const baseTypes = ['text', 'visual'];
  
  if (learningRate === 'fast') {
    baseTypes.push('advanced-problems', 'research-projects');
  } else if (learningRate === 'slow') {
    baseTypes.push('step-by-step-guides', 'practice-drills');
  }
  
  if (learningStyle === 'visual') {
    baseTypes.push('diagrams', 'charts', 'infographics');
  } else if (learningStyle === 'auditory') {
    baseTypes.push('audio-explanations', 'discussions');
  } else if (learningStyle === 'kinesthetic') {
    baseTypes.push('interactive-simulations', 'hands-on-activities');
  }
  
  return baseTypes;
}

function generateNextTopics(masteredTopics, strugglingTopics) {
  // Simple logic - in a real app this would be more sophisticated
  const suggestions = [];
  
  if (strugglingTopics.length > 0) {
    suggestions.push(`Review: ${strugglingTopics[0]}`);
  }
  
  if (masteredTopics.length > 0) {
    suggestions.push(`Advanced: ${masteredTopics[0]} Applications`);
  }
  
  return suggestions;
}
