import React, { useState } from 'react';

const RobotFactory = ({ payload, onComplete, disabled }) => {
  const slots = payload?.slots || [];
  const [slotIdx, setSlotIdx] = useState(0);
  const [correctCount, setCorrectCount] = useState(0);
  const [done, setDone] = useState(false);

  const slot = slots[slotIdx];

  const pickPart = (part) => {
    if (disabled || done || !slot) return;
    const ok = part.is_optimal;
    const next = correctCount + (ok ? 1 : 0);
    setCorrectCount(next);

    if (slotIdx >= slots.length - 1) {
      setDone(true);
      const pct = Math.round((next / slots.length) * 100);
      onComplete?.({ score: pct, gameType: payload?.style_id });
    } else {
      setSlotIdx((i) => i + 1);
    }
  };

  if (!slot) {
    return <p className="text-sm text-text-secondary">Assembly blueprint incomplete.</p>;
  }

  return (
    <div className="space-y-4">
      <p className="font-semibold">{payload.model_line}</p>
      <p className="text-sm text-text-secondary">{payload.assembly_objective}</p>
      <p className="text-sm">
        Slot <strong>{slot.slot_position}</strong> — needs: {slot.required_functional_trait}
      </p>
      <div className="grid gap-2">
        {(slot.compatible_parts || []).map((part) => (
          <button
            key={part.part_name}
            type="button"
            disabled={disabled || done}
            onClick={() => pickPart(part)}
            className="text-left p-3 border border-border rounded-lg hover:border-primary disabled:opacity-50"
          >
            <span className="font-medium">{part.part_name}</span>
            <span className="block text-xs text-text-secondary mt-1">{part.justification_text}</span>
          </button>
        ))}
      </div>
      <p className="text-xs text-text-secondary">
        {slotIdx + 1} / {slots.length}
      </p>
      {done && <p className="text-success-700">Assembly complete.</p>}
    </div>
  );
};

export default RobotFactory;
