import React, { useState } from 'react';

const SpaceMining = ({ payload, onComplete, disabled }) => {
  const asteroids = payload?.asteroids || [];
  const [idx, setIdx] = useState(0);
  const [yieldTotal, setYieldTotal] = useState(0);
  const [done, setDone] = useState(false);
  const [msg, setMsg] = useState(null);

  const rock = asteroids[idx];

  const pick = (answerIndex) => {
    if (disabled || done || !rock) return;
    const correct = answerIndex === rock.correct_index;
    if (correct) {
      const add = rock.yield_value || 10;
      const nextYield = yieldTotal + add;
      setYieldTotal(nextYield);
      setMsg(`Extracted +${add} units`);
      if (idx >= asteroids.length - 1) {
        setDone(true);
        onComplete?.({ score: Math.min(100, 40 + nextYield), gameType: payload?.style_id });
      } else {
        setTimeout(() => {
          setIdx((i) => i + 1);
          setMsg(null);
        }, 600);
      }
    } else {
      setMsg('Wrong calculation — drill missed the vein.');
    }
  };

  if (!rock) {
    return <p className="text-sm text-text-secondary">Sector data incomplete.</p>;
  }

  return (
    <div className="space-y-3 font-mono text-sm">
      <p className="text-primary font-semibold">{payload.sector_name}</p>
      <p className="text-text-secondary">{payload.market_demand_description}</p>
      <p className="text-xs">Yield: {yieldTotal}</p>
      <p>{rock.composition_clue}</p>
      <p className="font-medium text-text-primary">{rock.extraction_math_puzzle}</p>
      <div className="grid gap-2">
        {(rock.numeric_answers || []).map((n, i) => (
          <button
            key={`${rock.id}-${n}`}
            type="button"
            disabled={disabled || done}
            onClick={() => pick(i)}
            className="px-4 py-2 border border-border rounded-lg hover:border-primary disabled:opacity-50"
          >
            {n}
          </button>
        ))}
      </div>
      {msg && <p className="text-primary">{msg}</p>}
    </div>
  );
};

export default SpaceMining;
