import React, { useState } from 'react';

const TimeTravelFixer = ({ payload, onComplete, disabled }) => {
  const anchors = payload?.historical_anchors || [];
  const [idx, setIdx] = useState(0);
  const [fixed, setFixed] = useState(0);
  const [done, setDone] = useState(false);
  const [outcome, setOutcome] = useState(null);

  const anchor = anchors[idx];

  const pick = (optionIndex) => {
    if (disabled || done || !anchor) return;
    const correct = optionIndex === anchor.butterfly_effect_index;
    const nextFixed = fixed + (correct ? 1 : 0);
    setFixed(nextFixed);
    setOutcome(correct ? anchor.success_butterfly_outcome : 'Timeline fracture worsens…');

    if (idx >= anchors.length - 1) {
      setDone(true);
      onComplete?.({
        score: Math.round((nextFixed / anchors.length) * 100),
        gameType: payload?.style_id,
      });
    } else {
      setTimeout(() => {
        setIdx((i) => i + 1);
        setOutcome(null);
      }, 900);
    }
  };

  if (!anchor) {
    return <p className="text-sm text-text-secondary">Timeline data incomplete.</p>;
  }

  return (
    <div className="space-y-3">
      <p className="font-semibold text-primary">{payload.era_name}</p>
      <p className="text-sm italic">{payload.paradox_glitch_description}</p>
      <p className="text-sm">
        <span className="text-text-secondary">{anchor.year}:</span> {anchor.broken_event}
      </p>
      <div className="grid gap-2">
        {(anchor.correction_options || []).map((opt, i) => (
          <button
            key={opt}
            type="button"
            disabled={disabled || done}
            onClick={() => pick(i)}
            className="text-left px-4 py-2 border border-border rounded-lg hover:border-primary disabled:opacity-50"
          >
            {opt}
          </button>
        ))}
      </div>
      {outcome && <p className="text-sm text-primary-700">{outcome}</p>}
    </div>
  );
};

export default TimeTravelFixer;
