import React, { createContext, useState, useEffect, useCallback } from 'react';
import api, { setToken, getToken } from '../lib/api';

export const UserContext = createContext(null);

export const UserProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const applySession = useCallback((token, user) => {
    setToken(token);
    setCurrentUser({
      uid: user.uid || user.id,
      id: user.uid || user.id,
      email: user.email,
      name: user.name,
      avatarUrl: user.avatarUrl || null,
      role: user.role || 'student',
      isAdmin: Boolean(user.isAdmin),
    });
  }, []);

  useEffect(() => {
    const bootstrap = async () => {
      const token = getToken();
      if (!token) {
        setLoading(false);
        return;
      }

      try {
        const user = await api.me();
        setCurrentUser({
          uid: user.uid || user.id,
          id: user.uid || user.id,
          email: user.email,
          name: user.name,
          avatarUrl: user.avatarUrl || null,
          role: user.role || 'student',
          isAdmin: Boolean(user.isAdmin),
        });
      } catch {
        setToken(null);
        setCurrentUser(null);
      } finally {
        setLoading(false);
      }
    };

    bootstrap();
  }, []);

  const signIn = async (email, password) => {
    setError(null);
    setLoading(true);

    try {
      if (!email || !password) {
        throw new Error('Email and password are required');
      }

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        throw new Error('Please enter a valid email address');
      }

      const { token, user } = await api.login(email, password);
      applySession(token, user);
      return user;
    } catch (err) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const signUp = async (email, password, displayName) => {
    setError(null);
    setLoading(true);

    try {
      if (!email || !password || !displayName) {
        throw new Error('All fields are required');
      }

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        throw new Error('Please enter a valid email address');
      }

      if (password.length < 6) {
        throw new Error('Password must be at least 6 characters long');
      }

      const { token, user } = await api.register(email, password, displayName);
      applySession(token, user);
      return user;
    } catch (err) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const signOut = async () => {
    setError(null);
    setToken(null);
    setCurrentUser(null);
  };

  const updateUserProfile = async (updatedProfileData) => {
    setError(null);
    try {
      const user = await api.updateProfile({
        name: updatedProfileData.displayName || updatedProfileData.name,
        avatarUrl: updatedProfileData.photoURL || updatedProfileData.avatarUrl,
      });

      setCurrentUser((prev) => ({
        ...prev,
        name: user.name || prev.name,
        avatarUrl: user.avatarUrl ?? prev.avatarUrl,
      }));
    } catch (err) {
      setError(err.message);
      throw err;
    }
  };

  const changePassword = async (currentPassword, newPassword) => {
    setError(null);
    try {
      await api.changePassword(currentPassword, newPassword);
    } catch (err) {
      setError(err.message);
      throw err;
    }
  };

  const value = {
    currentUser,
    isAdmin: Boolean(currentUser?.isAdmin),
    signIn,
    signUp,
    signOut,
    updateUserProfile,
    changePassword,
    loading,
    error,
  };

  return <UserContext.Provider value={value}>{children}</UserContext.Provider>;
};
