import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const InteractiveQuiz = ({ quiz, uiAdaptations, onAnswer }) => {
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [isCorrect, setIsCorrect] = useState(null);
  const [timeSpent, setTimeSpent] = useState(0);
  const [confidence, setConfidence] = useState(50);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeSpent(prev => prev + 1);
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const handleAnswerSelect = (answerIndex) => {
    setSelectedAnswer(answerIndex);
  };

  const handleSubmit = () => {
    const correct = selectedAnswer === quiz.correctAnswer;
    setIsCorrect(correct);
    setShowExplanation(true);

    let performance = correct ? 80 : 40;
    if (timeSpent < 30) performance += 10;
    if (confidence > 70 && correct) performance += 10;

    onAnswer({
      performance: Math.min(performance, 100),
      correct,
      confidence: Number(confidence),
      timeSpent,
    });
  };

  const getTextSize = () => {
    switch (uiAdaptations.textSize) {
      case 'large':
        return 'text-lg leading-relaxed';
      case 'small':
        return 'text-sm leading-normal';
      default:
        return 'text-base leading-relaxed';
    }
  };

  const getContrastClass = () => {
    return uiAdaptations.contrast === 'high' ?'text-gray-900' :'text-text-primary';
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-6">
      {/* Quiz Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div 
            className="p-2 rounded-lg"
            style={{ backgroundColor: `${uiAdaptations.accentColor}20` }}
          >
            <Icon 
              name="HelpCircle" 
              size={20} 
              style={{ color: uiAdaptations.accentColor }}
            />
          </div>
          <div>
            <h2 className={`font-heading font-bold ${getContrastClass()} ${
              uiAdaptations.textSize === 'large' ? 'text-xl' : 'text-lg'
            }`}>
              Knowledge Check
            </h2>
            <p className="text-sm text-text-secondary">
              Test your understanding of the concept
            </p>
          </div>
        </div>
        
        <div className="text-right">
          <div className="text-sm font-mono text-text-primary">
            {formatTime(timeSpent)}
          </div>
          <div className="text-xs text-text-secondary">
            Time spent
          </div>
        </div>
      </div>

      {/* Question */}
      <div className="p-6 bg-surface-50 rounded-lg border border-border">
        <p className={`${getTextSize()} ${getContrastClass()} font-medium mb-6`}>
          {quiz.question}
        </p>

        {/* Answer Options */}
        <div className="space-y-3">
          {quiz.options.map((option, index) => (
            <button
              key={index}
              onClick={() => handleAnswerSelect(index)}
              disabled={showExplanation}
              className={`w-full p-4 text-left rounded-lg border-2 transition-all duration-200 ${
                selectedAnswer === index
                  ? showExplanation
                    ? index === quiz.correctAnswer
                      ? 'border-success bg-success-50 text-success-700' :'border-error bg-error-50 text-error-700' :'border-primary bg-primary-50 text-primary-700'
                  : showExplanation && index === quiz.correctAnswer
                    ? 'border-success bg-success-50 text-success-700' :'border-border bg-surface hover:bg-surface-50 text-text-primary'
              } ${showExplanation ? 'cursor-default' : 'cursor-pointer'}`}
            >
              <div className="flex items-center space-x-3">
                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${
                  selectedAnswer === index
                    ? showExplanation
                      ? index === quiz.correctAnswer
                        ? 'border-success bg-success text-white' :'border-error bg-error text-white' :'border-primary bg-primary text-white'
                    : showExplanation && index === quiz.correctAnswer
                      ? 'border-success bg-success text-white' :'border-border bg-surface'
                }`}>
                  {showExplanation && index === quiz.correctAnswer && (
                    <Icon name="Check" size={14} />
                  )}
                  {showExplanation && selectedAnswer === index && index !== quiz.correctAnswer && (
                    <Icon name="X" size={14} />
                  )}
                  {!showExplanation && selectedAnswer === index && (
                    <div className="w-2 h-2 bg-white rounded-full"></div>
                  )}
                </div>
                <span className={`${getTextSize()}`}>
                  {option}
                </span>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Confidence Slider */}
      {!showExplanation && selectedAnswer !== null && (
        <div className="p-4 bg-surface-50 rounded-lg border border-border">
          <div className="flex items-center justify-between mb-3">
            <label className="text-sm font-medium text-text-primary">
              How confident are you in your answer?
            </label>
            <span className="text-sm text-text-secondary">
              {confidence}%
            </span>
          </div>
          
          <input
            type="range"
            min="0"
            max="100"
            value={confidence}
            onChange={(e) => setConfidence(e.target.value)}
            className="w-full h-2 bg-surface-100 rounded-lg appearance-none cursor-pointer"
            style={{
              background: `linear-gradient(to right, ${uiAdaptations.accentColor} 0%, ${uiAdaptations.accentColor} ${confidence}%, #F3F4F6 ${confidence}%, #F3F4F6 100%)`
            }}
          />
          
          <div className="flex justify-between text-xs text-text-secondary mt-1">
            <span>Not sure</span>
            <span>Very confident</span>
          </div>
        </div>
      )}

      {/* Submit Button */}
      {selectedAnswer !== null && !showExplanation && (
        <button
          onClick={handleSubmit}
          className="w-full btn btn-primary py-3 text-base font-medium"
        >
          Submit Answer
        </button>
      )}

      {/* Explanation */}
      {showExplanation && (
        <div className={`p-6 rounded-lg border-2 ${
          isCorrect 
            ? 'border-success bg-success-50' :'border-warning bg-warning-50'
        }`}>
          <div className="flex items-start space-x-3">
            <div className={`p-2 rounded-full ${
              isCorrect ? 'bg-success text-white' : 'bg-warning text-white'
            }`}>
              <Icon name={isCorrect ? "CheckCircle" : "AlertCircle"} size={20} />
            </div>
            <div className="flex-1">
              <h3 className={`font-heading font-semibold mb-2 ${
                isCorrect ? 'text-success-700' : 'text-warning-700'
              } ${uiAdaptations.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
                {isCorrect ? 'Correct!' : 'Not quite right'}
              </h3>
              <p className={`${getTextSize()} ${
                isCorrect ? 'text-success-600' : 'text-warning-600'
              }`}>
                {quiz.explanation}
              </p>
            </div>
          </div>

          {/* Performance Feedback */}
          <div className="mt-4 pt-4 border-t border-current border-opacity-20">
            <div className="grid grid-cols-3 gap-4 text-center">
              <div>
                <div className={`text-lg font-heading font-bold ${
                  isCorrect ? 'text-success-700' : 'text-warning-700'
                }`}>
                  {isCorrect ? '✓' : '✗'}
                </div>
                <div className="text-xs text-text-secondary">Accuracy</div>
              </div>
              <div>
                <div className={`text-lg font-heading font-bold ${
                  isCorrect ? 'text-success-700' : 'text-warning-700'
                }`}>
                  {formatTime(timeSpent)}
                </div>
                <div className="text-xs text-text-secondary">Time</div>
              </div>
              <div>
                <div className={`text-lg font-heading font-bold ${
                  isCorrect ? 'text-success-700' : 'text-warning-700'
                }`}>
                  {confidence}%
                </div>
                <div className="text-xs text-text-secondary">Confidence</div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Next Steps */}
      {showExplanation && (
        <div className="flex items-center justify-between pt-4 border-t border-border">
          <div className="flex items-center space-x-2 text-text-secondary">
            <Icon name="Lightbulb" size={16} />
            <span className="text-sm">
              {isCorrect 
                ? 'Great job! Ready for the next challenge?'
                : 'Review the concept and try again when ready'
              }
            </span>
          </div>
          
          <div className="flex space-x-2">
            {!isCorrect && (
              <button
                onClick={() => {
                  setSelectedAnswer(null);
                  setShowExplanation(false);
                  setIsCorrect(null);
                  setTimeSpent(0);
                  setConfidence(50);
                }}
                className="btn btn-outline px-4 py-2 text-sm"
              >
                Try Again
              </button>
            )}
            <button className="btn btn-primary px-4 py-2 text-sm">
              Continue
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default InteractiveQuiz;