import React, { createContext, useState, useEffect, useContext } from 'react';
import { UserContext } from './UserContext';
import api from '../lib/api';

export const ProgressContext = createContext(null);

function normalizeProgressValue(progress = 0) {
  if (progress <= 1) {
    return Math.round(progress * 100);
  }
  return Math.round(progress);
}

function getNodePosition(index, subject, nodeId) {
  const subjectPositions = {
    mathematics: { baseX: 200, baseY: 100, spacing: 120 },
    programming: { baseX: 400, baseY: 300, spacing: 150 },
    history: { baseX: 100, baseY: 400, spacing: 130 },
    science: { baseX: 500, baseY: 150, spacing: 140 },
  };

  const pos = subjectPositions[subject] || { baseX: 300, baseY: 200, spacing: 100 };
  const offset = Math.floor(index / 4);
  const seed = hashString(`${nodeId}-${subject}-${index}`);
  const randomizer = mulberry32(seed);

  return {
    x: pos.baseX + (index % 2) * pos.spacing + randomizer() * 50,
    y: pos.baseY + offset * 80 + randomizer() * 40,
  };
}

function getNodeConnections(nodeId, prerequisite) {
  const connections = prerequisite ? [prerequisite] : [];
  const connectionMap = {
    'math-fundamentals': ['algebra-intro', 'geometry-basics'],
    'algebra-intro': ['linear-equations'],
    'programming-fundamentals': ['javascript-basics'],
    'ancient-civilizations': ['medieval-history'],
  };
  return connectionMap[nodeId] || connections;
}

function normalizeLearningNode(node, index = 0) {
  const progressValue = normalizeProgressValue(node.progress);
  const normalizedProgress =
    node.status === 'completed' && progressValue < 100 ? 100 : progressValue;
  const status =
    normalizedProgress >= 100 ? 'completed' : normalizedProgress > 0 ? 'in-progress' : 'not-started';

  return {
    ...node,
    progress: normalizedProgress,
    status,
    position: node.position || getNodePosition(index, node.subject, node.id),
    connections: node.connections || getNodeConnections(node.id, node.prerequisite),
    type: node.type || (node.difficulty === 'beginner' ? 'core' : 'advanced'),
    completed: normalizedProgress >= 100,
  };
}

function hydrateLearningNodes(nodes = []) {
  return nodes.map((node, index) => normalizeLearningNode(node, index));
}

function hashString(value) {
  let hash = 0;
  for (let i = 0; i < value.length; i += 1) {
    hash = (hash << 5) - hash + value.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

function mulberry32(seed) {
  let t = seed;
  return () => {
    t += 0x6d2b79f5;
    let result = Math.imul(t ^ (t >>> 15), t | 1);
    result ^= result + Math.imul(result ^ (result >>> 7), result | 61);
    return ((result ^ (result >>> 14)) >>> 0) / 4294967296;
  };
}

export const ProgressProvider = ({ children }) => {
  const { currentUser } = useContext(UserContext);
  const [learningNodes, setLearningNodes] = useState([]);
  const [sessionLogs, setSessionLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const loadProgress = async () => {
    if (!currentUser?.uid) {
      setLearningNodes([]);
      setSessionLogs([]);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const [nodes, sessions] = await Promise.all([api.getNodes(), api.getSessions()]);
      setLearningNodes(hydrateLearningNodes(nodes));
      setSessionLogs(sessions);
    } catch (err) {
      console.error('Error loading progress:', err);
      setError(err.message || 'Failed to load progress');
    } finally {
      setLoading(false);
    }
  };

  const updateNodeProgress = async (nodeId, newProgress, isCompleted) => {
    const updatedProgress = Math.min(Math.max(normalizeProgressValue(newProgress), 0), 100);
    const completedStatus = isCompleted !== undefined ? isCompleted : updatedProgress >= 100;
    const status = completedStatus
      ? 'completed'
      : updatedProgress > 0
        ? 'in-progress'
        : 'not-started';

    setLearningNodes((prevNodes) =>
      prevNodes.map((node) =>
        node.id === nodeId
          ? {
              ...node,
              progress: updatedProgress,
              completed: completedStatus,
              status,
              lastAccessed: new Date().toISOString().split('T')[0],
            }
          : node
      )
    );

    if (!currentUser?.uid) return;

    try {
      await api.updateNode(nodeId, {
        progress: updatedProgress,
        completed: completedStatus,
        status,
        lastAccessed: new Date().toISOString().split('T')[0],
      });
    } catch (err) {
      console.error('Error saving progress:', err);
      setError(err.message || 'Failed to save progress');
    }
  };

  const recordLearningSession = async (sessionDetails) => {
    const sessionEntry = {
      id: sessionDetails.id || `session_${Date.now()}`,
      createdAt: new Date().toISOString(),
      ...sessionDetails,
    };

    setSessionLogs((prev) => [sessionEntry, ...prev]);

    if (!currentUser?.uid) return;

    try {
      await api.recordSession(sessionEntry);
    } catch (err) {
      console.error('Error saving session:', err);
      setError(err.message || 'Failed to save session');
    }
  };

  const resetAllProgress = async () => {
    if (!currentUser?.uid) return;

    try {
      setLoading(true);
      const nodes = await api.resetNodes();
      setLearningNodes(hydrateLearningNodes(nodes));
      setSessionLogs([]);
    } catch (err) {
      console.error('Error resetting progress:', err);
      setError(err.message || 'Failed to reset progress');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadProgress();
  }, [currentUser?.uid]);

  return (
    <ProgressContext.Provider
      value={{
        learningNodes,
        updateNodeProgress,
        recordLearningSession,
        sessionLogs,
        loading,
        resetAllProgress,
        error,
        refreshProgress: loadProgress,
      }}
    >
      {children}
    </ProgressContext.Provider>
  );
};
