import React, { useState, useContext } from 'react';
import { UserContext } from '../contexts/UserContext';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import Icon from '../components/AppIcon';
import api from '../lib/api';

const LoginPage = () => {
  const { signIn, signUp, loading, currentUser, error: authError } = useContext(UserContext);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [isSignUp, setIsSignUp] = useState(false);
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [validationErrors, setValidationErrors] = useState({});
  const [isResettingPassword, setIsResettingPassword] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const navigate = useNavigate();
  const location = useLocation();

  const from = location.state?.from?.pathname || '/learn';
  const MIN_PASSWORD_LENGTH = 8;

  // Real-time validation
  const validateEmail = (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) return 'Email is required';
    if (!emailRegex.test(email)) return 'Please enter a valid email address';
    return '';
  };

  const validatePassword = (password) => {
    if (!password) return 'Password is required';
    if (isSignUp && password.length < MIN_PASSWORD_LENGTH) {
      return `Password must be at least ${MIN_PASSWORD_LENGTH} characters long`;
    }
    return '';
  };

  const validateDisplayName = (name) => {
    if (isSignUp && !name) return 'Name is required';
    if (isSignUp && name.length < 2) return 'Name must be at least 2 characters long';
    return '';
  };

  const handleEmailChange = (e) => {
    const value = e.target.value;
    setEmail(value);
    setValidationErrors(prev => ({ ...prev, email: validateEmail(value) }));
  };

  const handlePasswordChange = (e) => {
    const value = e.target.value;
    setPassword(value);
    setValidationErrors(prev => ({ ...prev, password: validatePassword(value) }));
  };

  const handleDisplayNameChange = (e) => {
    const value = e.target.value;
    setDisplayName(value);
    setValidationErrors(prev => ({ ...prev, displayName: validateDisplayName(value) }));
  };

  const handlePasswordReset = async () => {
    if (!email) {
      setError('Please enter your email address first');
      return;
    }

    const emailError = validateEmail(email);
    if (emailError) {
      setError(emailError);
      return;
    }

    setIsResettingPassword(true);
    setError('');
    try {
      const result = await api.forgotPassword(email);
      setSuccessMessage(
        result.message ||
          'If an account exists for that email, check your inbox for reset instructions.'
      );
    } catch {
      setError('Could not process reset request. Try again later.');
    } finally {
      setIsResettingPassword(false);
    }
  };

  if (currentUser && !loading) {
    navigate(from, { replace: true });
    return null;
  }

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate all fields
    const emailError = validateEmail(email);
    const passwordError = validatePassword(password);
    const nameError = validateDisplayName(displayName);

    setValidationErrors({
      email: emailError,
      password: passwordError,
      displayName: nameError
    });

    if (emailError || passwordError || nameError) {
      setError('Please fix the errors above');
      return;
    }

    try {
      setError('');
      if (isSignUp) {
        await signUp(email, password, displayName);
      } else {
        await signIn(email, password);
      }
      navigate(from, { replace: true });
    } catch (error) {
      setError(error.message);
    }
  };

  const toggleMode = () => {
    setIsSignUp(!isSignUp);
    setError('');
    setSuccessMessage('');
    setValidationErrors({});
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="flex flex-col items-center space-y-4">
          <div className="w-8 h-8 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center animate-pulse">
            <Icon name="Brain" size={20} color="white" strokeWidth={2.5} />
          </div>
          <p className="text-text-secondary">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <div className="bg-surface p-8 rounded-lg shadow-warm-lg w-full max-w-md">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-12 h-12 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center mx-auto mb-4">
            <Icon name="Brain" size={24} color="white" strokeWidth={2.5} />
          </div>
          <h1 className="text-2xl font-heading font-bold text-text-primary">
            {isSignUp ? 'Create Account' : 'Welcome Back'}
          </h1>
          <p className="text-text-secondary mt-2">
            {isSignUp ? 'Start your adaptive learning journey' : 'Continue your learning journey'}
          </p>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-6">
          {(error || authError) && (
            <div className="bg-error-50 border border-error text-error text-sm p-3 rounded-lg">
              {error || authError}
            </div>
          )}
          {successMessage && (
            <div className="bg-success-50 border border-success text-success-700 text-sm p-3 rounded-lg">
              {successMessage}
            </div>
          )}

          {isSignUp && (
            <div>
              <label className="block text-sm font-medium text-text-primary mb-2">
                Full Name
              </label>
              <input
                type="text"
                className={`w-full px-3 py-2 border rounded-lg bg-surface-50 text-text-primary placeholder:text-text-secondary focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all duration-200 ${
                  validationErrors.displayName ? 'border-error' : 'border-border'
                }`}
                placeholder="Enter your full name"
                value={displayName}
                onChange={handleDisplayNameChange}
                autoFocus={isSignUp}
              />
              {validationErrors.displayName && (
                <p className="mt-1 text-sm text-error">{validationErrors.displayName}</p>
              )}
            </div>
          )}

          <div>
            <label className="block text-sm font-medium text-text-primary mb-2">
              Email Address
            </label>
            <input
              type="email"
              className={`w-full px-3 py-2 border rounded-lg bg-surface-50 text-text-primary placeholder:text-text-secondary focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all duration-200 ${
                validationErrors.email ? 'border-error' : 'border-border'
              }`}
              placeholder="Enter your email"
              value={email}
              onChange={handleEmailChange}
              autoFocus={!isSignUp}
            />
            {validationErrors.email && (
              <p className="mt-1 text-sm text-error">{validationErrors.email}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-text-primary mb-2">
              Password
            </label>
            <div className="relative">
              <input
                type={showPassword ? 'text' : 'password'}
                className={`w-full px-3 py-2 pr-10 border rounded-lg bg-surface-50 text-text-primary placeholder:text-text-secondary focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all duration-200 ${
                  validationErrors.password ? 'border-error' : 'border-border'
                }`}
                placeholder="Enter your password"
                value={password}
                onChange={handlePasswordChange}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute inset-y-0 right-0 pr-3 flex items-center text-text-secondary hover:text-text-primary"
              >
                <Icon name={showPassword ? 'EyeOff' : 'Eye'} size={16} />
              </button>
            </div>
            {validationErrors.password && (
              <p className="mt-1 text-sm text-error">{validationErrors.password}</p>
            )}
            {isSignUp && (
              <p className="mt-1 text-xs text-text-secondary">
                Password must be at least 8 characters long
              </p>
            )}
          </div>

          <button
            type="submit"
            disabled={loading || isResettingPassword}
            className="w-full bg-primary text-white py-3 rounded-lg font-medium hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? (
              <div className="flex items-center justify-center space-x-2">
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                <span>{isSignUp ? 'Creating Account...' : 'Signing In...'}</span>
              </div>
            ) : (
              isSignUp ? 'Create Account' : 'Sign In'
            )}
          </button>

          {/* Forgot Password */}
          {!isSignUp && (
            <div className="text-center">
              <button
                type="button"
                onClick={handlePasswordReset}
                disabled={isResettingPassword}
                className="text-sm text-primary hover:text-primary-700 transition-colors duration-200 disabled:opacity-50"
              >
                {isResettingPassword ? 'Sending...' : 'Forgot your password?'}
              </button>
            </div>
          )}
        </form>

        {/* Toggle Mode */}
        <div className="mt-6 text-center">
          <p className="text-text-secondary text-sm">
            {isSignUp ? 'Already have an account?' : "Don't have an account?"}
            <button
              type="button"
              onClick={toggleMode}
              className="ml-1 text-primary font-medium hover:text-primary-700 transition-colors duration-200"
            >
              {isSignUp ? 'Sign In' : 'Sign Up'}
            </button>
          </p>
          <p className="text-xs text-text-secondary mt-4">
            By continuing you agree to our{' '}
            <Link to="/terms" className="text-primary hover:underline">Terms</Link>
            {' '}and{' '}
            <Link to="/privacy" className="text-primary hover:underline">Privacy Policy</Link>.
          </p>
        </div>

      </div>
    </div>
  );
};

export default LoginPage;
