import React, { useState } from 'react';

const DungeonCrawler = ({ payload, onComplete, disabled }) => {
  const rooms = payload?.rooms || [];
  const [roomIdx, setRoomIdx] = useState(0);
  const [done, setDone] = useState(false);
  const [trap, setTrap] = useState(null);

  const room = rooms[roomIdx];

  const choose = (door) => {
    if (disabled || done || !room) return;
    if (door === room.correct_door) {
      setTrap(null);
      if (roomIdx >= rooms.length - 1) {
        setDone(true);
        onComplete?.({ score: 90, gameType: payload?.style_id });
      } else {
        setTimeout(() => setRoomIdx((i) => i + 1), 500);
      }
    } else {
      setTrap(room.trap_description);
    }
  };

  if (!room) {
    return <p className="text-sm text-text-secondary">Dungeon data incomplete.</p>;
  }

  return (
    <div className="space-y-4">
      <h4 className="font-semibold">{room.room_name}</h4>
      <div className="grid md:grid-cols-2 gap-3">
        <button
          type="button"
          disabled={disabled || done}
          onClick={() => choose('left')}
          className="p-4 border border-border rounded-lg hover:border-primary text-left disabled:opacity-50"
        >
          <span className="text-xs text-text-secondary block mb-1">Left door</span>
          {room.door_left_inscription}
        </button>
        <button
          type="button"
          disabled={disabled || done}
          onClick={() => choose('right')}
          className="p-4 border border-border rounded-lg hover:border-primary text-left disabled:opacity-50"
        >
          <span className="text-xs text-text-secondary block mb-1">Right door</span>
          {room.door_right_inscription}
        </button>
      </div>
      {trap && <p className="text-error text-sm">{trap}</p>}
      {done && <p className="text-success-700 font-medium">Dungeon cleared!</p>}
    </div>
  );
};

export default DungeonCrawler;
