import React from 'react';

const LoadingState = ({ message = 'Loading...', fullScreen = true }) => (
  <div
    className={`flex items-center justify-center ${fullScreen ? 'min-h-[50vh]' : 'py-12'}`}
    role="status"
    aria-live="polite"
    aria-busy="true"
  >
    <div className="text-center">
      <div
        className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-4"
        aria-hidden="true"
      />
      <p className="text-text-secondary">{message}</p>
    </div>
  </div>
);

export default LoadingState;
