import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Icon from '../AppIcon';

const SessionControlPanel = ({
  isSessionActive = false,
  sessionType = 'adaptive', // 'adaptive', 'collaborative', 'ar'
  sessionDuration = 0,
  collaborators = [],
  onSessionToggle,
  onModeChange,
  onAccessibilityToggle
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [currentMode, setCurrentMode] = useState(sessionType);
  const [isARSupported, setIsARSupported] = useState(false);
  const [accessibilityFeatures, setAccessibilityFeatures] = useState({
    highContrast: false,
    largeText: false,
    reducedMotion: false,
    screenReader: false
  });
  const [sessionTimer, setSessionTimer] = useState(sessionDuration);
  const location = useLocation();

  // Check AR support
  useEffect(() => {
    if ('xr' in navigator) {
      navigator.xr?.isSessionSupported('immersive-ar').then(setIsARSupported);
    }
  }, []);

  // Session timer
  useEffect(() => {
    let interval;
    if (isSessionActive) {
      interval = setInterval(() => {
        setSessionTimer(prev => prev + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isSessionActive]);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleModeChange = (newMode) => {
    setCurrentMode(newMode);
    onModeChange?.(newMode);
  };

  const handleAccessibilityToggle = (feature) => {
    setAccessibilityFeatures(prev => ({
      ...prev,
      [feature]: !prev[feature]
    }));
    onAccessibilityToggle?.(feature, !accessibilityFeatures[feature]);
  };

  const getSessionIcon = () => {
    switch (currentMode) {
      case 'collaborative':
        return 'Users';
      case 'ar':
        return 'Glasses';
      default:
        return 'Brain';
    }
  };

  const getSessionColor = () => {
    switch (currentMode) {
      case 'collaborative':
        return 'secondary';
      case 'ar':
        return 'accent';
      default:
        return 'primary';
    }
  };

  const shouldShowPanel = () => {
    return location.pathname === '/interactive-learning-session' || 
           location.pathname === '/adaptive-learning-dashboard';
  };

  if (!shouldShowPanel()) return null;

  return (
    <div className="fixed bottom-4 right-4 z-40 lg:bottom-6 lg:right-6">
      <div 
        className={`bg-surface border border-border rounded-xl shadow-warm-lg transition-all duration-300 ${
          isExpanded ? 'w-80 p-4' : 'w-14 h-14 p-2'
        }`}
        onMouseEnter={() => setIsExpanded(true)}
        onMouseLeave={() => setIsExpanded(false)}
      >
        {!isExpanded ? (
          // Collapsed State - Session Status Only
          <div className="relative w-10 h-10">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
              isSessionActive 
                ? `bg-${getSessionColor()} text-white` 
                : 'bg-surface-100 text-text-secondary'
            } transition-all duration-200`}>
              <Icon name={getSessionIcon()} size={18} />
            </div>
            {isSessionActive && (
              <div className="absolute -top-1 -right-1 w-4 h-4 bg-success rounded-full flex items-center justify-center">
                <div className="w-2 h-2 bg-white rounded-full animate-pulse"></div>
              </div>
            )}
          </div>
        ) : (
          // Expanded State - Full Control Panel
          <div className="animate-fade-in">
            {/* Header */}
            <div className="flex items-center justify-between mb-4">
              <div>
                <h3 className="font-heading font-semibold text-text-primary text-sm">
                  Session Control
                </h3>
                <p className="text-xs text-text-secondary font-caption">
                  {isSessionActive ? `Active • ${formatTime(sessionTimer)}` : 'Ready to start'}
                </p>
              </div>
              <div className={`p-2 rounded-lg ${
                isSessionActive ? `bg-${getSessionColor()}-50` : 'bg-surface-100'
              }`}>
                <Icon 
                  name={getSessionIcon()} 
                  size={16} 
                  className={isSessionActive ? `text-${getSessionColor()}` : 'text-text-secondary'}
                />
              </div>
            </div>

            {/* Session Controls */}
            <div className="space-y-3 mb-4">
              <button
                onClick={onSessionToggle}
                className={`w-full py-3 px-4 rounded-lg font-medium text-sm transition-all duration-200 active:transform active:translate-y-px ${
                  isSessionActive
                    ? 'bg-error text-white hover:bg-error-600'
                    : `bg-${getSessionColor()} text-white hover:bg-${getSessionColor()}-700`
                }`}
              >
                {isSessionActive ? (
                  <div className="flex items-center justify-center space-x-2">
                    <Icon name="Square" size={16} />
                    <span>End Session</span>
                  </div>
                ) : (
                  <div className="flex items-center justify-center space-x-2">
                    <Icon name="Play" size={16} />
                    <span>Start Learning</span>
                  </div>
                )}
              </button>

              {/* Mode Selection */}
              <div className="space-y-2">
                <label className="text-xs font-caption text-text-secondary">Learning Mode</label>
                <div className="grid grid-cols-3 gap-1 p-1 bg-surface-50 rounded-lg">
                  <button
                    onClick={() => handleModeChange('adaptive')}
                    className={`p-2 rounded text-xs font-medium transition-all duration-200 ${
                      currentMode === 'adaptive' ?'bg-primary text-white shadow-sm' :'text-text-secondary hover:text-text-primary'
                    }`}
                  >
                    <Icon name="Brain" size={14} className="mx-auto mb-1" />
                    <div>AI</div>
                  </button>
                  <button
                    onClick={() => handleModeChange('collaborative')}
                    className={`p-2 rounded text-xs font-medium transition-all duration-200 ${
                      currentMode === 'collaborative' ?'bg-secondary text-white shadow-sm' :'text-text-secondary hover:text-text-primary'
                    }`}
                  >
                    <Icon name="Users" size={14} className="mx-auto mb-1" />
                    <div>Group</div>
                  </button>
                  <button
                    onClick={() => handleModeChange('ar')}
                    disabled={!isARSupported}
                    className={`p-2 rounded text-xs font-medium transition-all duration-200 ${
                      currentMode === 'ar' ?'bg-accent text-white shadow-sm'
                        : isARSupported 
                          ? 'text-text-secondary hover:text-text-primary' :'text-text-tertiary cursor-not-allowed'
                    }`}
                  >
                    <Icon name="Glasses" size={14} className="mx-auto mb-1" />
                    <div>AR</div>
                  </button>
                </div>
              </div>
            </div>

            {/* Collaborative Features */}
            {currentMode === 'collaborative' && (
              <div className="mb-4 p-3 bg-secondary-50 rounded-lg">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs font-caption text-text-secondary">Collaborators</span>
                  <button className="text-xs text-secondary hover:text-secondary-700 font-medium">
                    Invite
                  </button>
                </div>
                <div className="flex -space-x-2">
                  {collaborators.slice(0, 3).map((collaborator, index) => (
                    <div
                      key={index}
                      className="w-6 h-6 bg-gradient-to-br from-primary-500 to-secondary rounded-full border-2 border-white flex items-center justify-center"
                    >
                      <Icon name="User" size={12} color="white" />
                    </div>
                  ))}
                  {collaborators.length > 3 && (
                    <div className="w-6 h-6 bg-surface-100 rounded-full border-2 border-white flex items-center justify-center">
                      <span className="text-xs font-medium text-text-secondary">
                        +{collaborators.length - 3}
                      </span>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Accessibility Controls */}
            <div className="space-y-2">
              <label className="text-xs font-caption text-text-secondary">Accessibility</label>
              <div className="grid grid-cols-2 gap-2">
                <button
                  onClick={() => handleAccessibilityToggle('highContrast')}
                  className={`p-2 rounded-lg text-xs font-medium transition-all duration-200 ${
                    accessibilityFeatures.highContrast
                      ? 'bg-success text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                  }`}
                >
                  <Icon name="Contrast" size={14} className="mx-auto mb-1" />
                  <div>Contrast</div>
                </button>
                <button
                  onClick={() => handleAccessibilityToggle('largeText')}
                  className={`p-2 rounded-lg text-xs font-medium transition-all duration-200 ${
                    accessibilityFeatures.largeText
                      ? 'bg-success text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                  }`}
                >
                  <Icon name="Type" size={14} className="mx-auto mb-1" />
                  <div>Large Text</div>
                </button>
                <button
                  onClick={() => handleAccessibilityToggle('reducedMotion')}
                  className={`p-2 rounded-lg text-xs font-medium transition-all duration-200 ${
                    accessibilityFeatures.reducedMotion
                      ? 'bg-success text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                  }`}
                >
                  <Icon name="Pause" size={14} className="mx-auto mb-1" />
                  <div>Motion</div>
                </button>
                <button
                  onClick={() => handleAccessibilityToggle('screenReader')}
                  className={`p-2 rounded-lg text-xs font-medium transition-all duration-200 ${
                    accessibilityFeatures.screenReader
                      ? 'bg-success text-white' :'bg-surface-50 text-text-secondary hover:bg-surface-100'
                  }`}
                >
                  <Icon name="Volume2" size={14} className="mx-auto mb-1" />
                  <div>Audio</div>
                </button>
              </div>
            </div>

            {/* Quick Stats */}
            {isSessionActive && (
              <div className="mt-4 pt-3 border-t border-border">
                <div className="grid grid-cols-3 gap-3 text-center">
                  <div>
                    <p className="text-lg font-heading font-semibold text-text-primary">
                      {Math.floor(sessionTimer / 60)}
                    </p>
                    <p className="text-xs text-text-secondary">minutes</p>
                  </div>
                  <div>
                    <p className="text-lg font-heading font-semibold text-text-primary">
                      7
                    </p>
                    <p className="text-xs text-text-secondary">topics</p>
                  </div>
                  <div>
                    <p className="text-lg font-heading font-semibold text-text-primary">
                      85%
                    </p>
                    <p className="text-xs text-text-secondary">accuracy</p>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SessionControlPanel;