import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import Icon from '../AppIcon';

const DynamicContextMenu = ({
  isVisible = false,
  position = { x: 0, y: 0 },
  contextData = {},
  onClose,
  onAction
}) => {
  const [menuItems, setMenuItems] = useState([]);
  const [isAnimating, setIsAnimating] = useState(false);
  const menuRef = useRef(null);
  const location = useLocation();

  // Generate contextual menu items based on current page and AI analysis
  useEffect(() => {
    if (isVisible) {
      setIsAnimating(true);
      generateContextualItems();
    }
  }, [isVisible, location.pathname, contextData]);

  const generateContextualItems = () => {
    let items = [];

    // Base accessibility actions (always available)
    const accessibilityItems = [
      {
        id: 'accessibility',
        label: 'Accessibility Options',
        icon: 'Accessibility',
        type: 'submenu',
        items: [
          { id: 'high-contrast', label: 'Toggle High Contrast', icon: 'Contrast', action: 'toggle-contrast' },
          { id: 'large-text', label: 'Increase Text Size', icon: 'Type', action: 'increase-text' },
          { id: 'reduce-motion', label: 'Reduce Motion', icon: 'Pause', action: 'reduce-motion' },
          { id: 'screen-reader', label: 'Screen Reader Mode', icon: 'Volume2', action: 'screen-reader' }
        ]
      }
    ];

    // Page-specific items
    switch (location.pathname) {
      case '/adaptive-learning-dashboard':
        items = [
          { id: 'customize-path', label: 'Customize Learning Path', icon: 'Route', action: 'customize-path' },
          { id: 'ai-recommendations', label: 'Get AI Recommendations', icon: 'Sparkles', action: 'ai-recommend' },
          { id: 'bookmark-topic', label: 'Bookmark This Topic', icon: 'Bookmark', action: 'bookmark' },
          { id: 'share-progress', label: 'Share Progress', icon: 'Share2', action: 'share-progress' },
          ...accessibilityItems
        ];
        break;

      case '/interactive-learning-session':
        items = [
          { id: 'pause-session', label: 'Pause Session', icon: 'Pause', action: 'pause-session' },
          { id: 'take-note', label: 'Take Quick Note', icon: 'PenTool', action: 'take-note' },
          { id: 'highlight-content', label: 'Highlight Content', icon: 'Highlighter', action: 'highlight' },
          { id: 'ask-ai', label: 'Ask AI Assistant', icon: 'MessageCircle', action: 'ask-ai' },
          { id: 'collaborate', label: 'Invite Collaborator', icon: 'UserPlus', action: 'invite-collaborator' },
          ...accessibilityItems
        ];
        break;

      case '/progress-analytics-dashboard':
        items = [
          { id: 'export-data', label: 'Export Analytics', icon: 'Download', action: 'export-data' },
          { id: 'compare-peers', label: 'Compare with Peers', icon: 'Users', action: 'compare-peers' },
          { id: 'set-goals', label: 'Set Learning Goals', icon: 'Target', action: 'set-goals' },
          { id: 'schedule-review', label: 'Schedule Review', icon: 'Calendar', action: 'schedule-review' },
          ...accessibilityItems
        ];
        break;

      case '/user-profile-settings':
        items = [
          { id: 'backup-data', label: 'Backup Learning Data', icon: 'Shield', action: 'backup-data' },
          { id: 'privacy-settings', label: 'Privacy Settings', icon: 'Lock', action: 'privacy-settings' },
          { id: 'notification-prefs', label: 'Notification Preferences', icon: 'Bell', action: 'notification-prefs' },
          { id: 'learning-style', label: 'Update Learning Style', icon: 'Brain', action: 'learning-style' },
          ...accessibilityItems
        ];
        break;

      default:
        items = [
          { id: 'help', label: 'Get Help', icon: 'HelpCircle', action: 'help' },
          { id: 'feedback', label: 'Send Feedback', icon: 'MessageSquare', action: 'feedback' },
          ...accessibilityItems
        ];
    }

    // Add AI-generated contextual items based on user behavior
    if (contextData.aiSuggestions) {
      const aiItems = contextData.aiSuggestions.map((suggestion, index) => ({
        id: `ai-${index}`,
        label: suggestion.label,
        icon: suggestion.icon || 'Sparkles',
        action: suggestion.action,
        isAI: true
      }));
      items.unshift(...aiItems);
    }

    setMenuItems(items);
  };

  const handleItemClick = (item) => {
    if (item.type === 'submenu') {
      // Handle submenu expansion
      return;
    }
    
    setIsAnimating(false);
    onAction?.(item.action, item);
    setTimeout(() => onClose?.(), 150);
  };

  const handleClickOutside = (event) => {
    if (menuRef.current && !menuRef.current.contains(event.target)) {
      onClose?.();
    }
  };

  useEffect(() => {
    if (isVisible) {
      document.addEventListener('mousedown', handleClickOutside);
      document.addEventListener('keydown', handleKeyDown);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isVisible]);

  const handleKeyDown = (event) => {
    if (event.key === 'Escape') {
      onClose?.();
    }
  };

  if (!isVisible) return null;

  return (
    <div
      ref={menuRef}
      className={`fixed z-max bg-surface border border-border rounded-lg shadow-warm-xl min-w-48 max-w-64 transition-all duration-200 ${
        isAnimating ? 'animate-scale-in' : 'opacity-0'
      }`}
      style={{
        left: `${position.x}px`,
        top: `${position.y}px`,
        transform: 'translate(-50%, -10px)'
      }}
    >
      <div className="py-2">
        {menuItems.map((item, index) => (
          <div key={item.id}>
            {item.type === 'submenu' ? (
              <div className="relative group">
                <button
                  className="w-full flex items-center justify-between px-4 py-2 text-sm text-text-primary hover:bg-surface-50 transition-colors duration-200"
                  onClick={() => handleItemClick(item)}
                >
                  <div className="flex items-center space-x-3">
                    <Icon name={item.icon} size={16} className="text-text-secondary" />
                    <span>{item.label}</span>
                  </div>
                  <Icon name="ChevronRight" size={14} className="text-text-secondary" />
                </button>
                
                {/* Submenu */}
                <div className="absolute left-full top-0 ml-1 bg-surface border border-border rounded-lg shadow-warm-lg min-w-48 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-max">
                  <div className="py-2">
                    {item.items.map((subItem) => (
                      <button
                        key={subItem.id}
                        onClick={() => handleItemClick(subItem)}
                        className="w-full flex items-center space-x-3 px-4 py-2 text-sm text-text-primary hover:bg-surface-50 transition-colors duration-200"
                      >
                        <Icon name={subItem.icon} size={16} className="text-text-secondary" />
                        <span>{subItem.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            ) : (
              <button
                onClick={() => handleItemClick(item)}
                className={`w-full flex items-center space-x-3 px-4 py-2 text-sm transition-colors duration-200 ${
                  item.isAI 
                    ? 'text-primary hover:bg-primary-50 border-l-2 border-primary' :'text-text-primary hover:bg-surface-50'
                }`}
              >
                <Icon 
                  name={item.icon} 
                  size={16} 
                  className={item.isAI ? 'text-primary' : 'text-text-secondary'} 
                />
                <span className="flex-1 text-left">{item.label}</span>
                {item.isAI && (
                  <div className="w-2 h-2 bg-primary rounded-full animate-pulse"></div>
                )}
              </button>
            )}
            
            {/* Separator */}
            {index < menuItems.length - 1 && 
             (item.isAI || (menuItems[index + 1] && !menuItems[index + 1].isAI && item.isAI !== menuItems[index + 1].isAI)) && (
              <div className="my-1 border-t border-border"></div>
            )}
          </div>
        ))}
      </div>

      {/* AI Attribution */}
      {contextData.aiSuggestions && contextData.aiSuggestions.length > 0 && (
        <div className="border-t border-border px-4 py-2 bg-surface-50">
          <div className="flex items-center space-x-2">
            <Icon name="Sparkles" size={12} className="text-primary" />
            <span className="text-xs text-text-secondary font-caption">
              AI-powered suggestions
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

export default DynamicContextMenu;