import React, { useState } from 'react';

const CardBattler = ({ payload, onComplete, disabled }) => {
  const matchups = payload?.matchups || [];
  const hand = payload?.player_hand || [];
  const [turn, setTurn] = useState(0);
  const [wins, setWins] = useState(0);
  const [done, setDone] = useState(false);
  const [feedback, setFeedback] = useState(null);

  const m = matchups[turn];

  const playCard = (cardName) => {
    if (disabled || done || !m) return;
    const correct = cardName === m.winning_counter_card_name;
    const nextWins = wins + (correct ? 1 : 0);
    setWins(nextWins);
    setFeedback(
      correct ? m.strategic_reasoning_clue || 'Perfect counter!' : 'Enemy breaks through your defense.'
    );

    if (turn >= matchups.length - 1) {
      setDone(true);
      onComplete?.({
        score: Math.round((nextWins / matchups.length) * 100),
        gameType: payload?.style_id,
      });
    } else {
      setTimeout(() => {
        setTurn((t) => t + 1);
        setFeedback(null);
      }, 800);
    }
  };

  if (!m) {
    return <p className="text-sm text-text-secondary">Deck data incomplete.</p>;
  }

  return (
    <div className="space-y-4">
      <p className="font-semibold">{payload.deck_theme}</p>
      <p className="text-sm">
        Enemy plays: <strong>{m.enemy_card_played}</strong>
      </p>
      <p className="text-xs text-text-secondary">{m.strategic_reasoning_clue}</p>
      <div className="flex flex-wrap gap-2">
        {hand.map((card) => (
          <button
            key={card.card_name}
            type="button"
            disabled={disabled || done}
            onClick={() => playCard(card.card_name)}
            className="px-3 py-2 border border-border rounded-lg bg-surface hover:border-primary text-left disabled:opacity-50"
          >
            <span className="font-medium block">{card.card_name}</span>
            <span className="text-xs text-text-secondary">⚡ {card.power_rating}</span>
          </button>
        ))}
      </div>
      {feedback && <p className="text-sm text-primary">{feedback}</p>}
      <p className="text-xs text-text-secondary">Turn {turn + 1}/{matchups.length}</p>
    </div>
  );
};

export default CardBattler;
