import React, { useState } from 'react';

const RpgBossBattle = ({ payload, onComplete, disabled }) => {
  const [phaseIdx, setPhaseIdx] = useState(0);
  const [hp, setHp] = useState(payload?.boss_hp ?? 100);
  const [done, setDone] = useState(false);
  const [feedback, setFeedback] = useState(null);

  const phases = payload?.phases || [];
  const phase = phases[phaseIdx];

  const pick = (index) => {
    if (disabled || done || !phase) return;
    const correct = index === phase.correct_index;
    if (correct) {
      const dmg = phase.damage_inflicted || 30;
      const nextHp = Math.max(0, hp - dmg);
      setHp(nextHp);
      setFeedback(`Hit! −${dmg} HP`);
      if (nextHp <= 0 || phaseIdx >= phases.length - 1) {
        setDone(true);
        onComplete?.({ score: 95, gameType: payload?.style_id });
      } else {
        setTimeout(() => {
          setPhaseIdx((i) => i + 1);
          setFeedback(null);
        }, 700);
      }
    } else {
      setFeedback('Miss! Try another tactic.');
    }
  };

  if (!phase) {
    return <p className="text-sm text-text-secondary">Boss battle data incomplete.</p>;
  }

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <div>
          <p className="text-xs uppercase text-text-secondary">Boss</p>
          <p className="font-semibold text-lg">{payload.boss_name}</p>
        </div>
        <div className="text-right">
          <p className="text-xs text-text-secondary">HP</p>
          <p className="font-mono text-xl text-error">{hp}</p>
        </div>
      </div>
      <p className="text-sm text-text-secondary">{payload.mechanic_tutorial}</p>
      <p className="italic text-primary-700">{phase.boss_action}</p>
      <p className="font-medium">{phase.challenge_question}</p>
      <div className="grid gap-2">
        {(phase.options || []).map((opt, i) => (
          <button
            key={opt}
            type="button"
            disabled={disabled || done}
            onClick={() => pick(i)}
            className="text-left px-4 py-3 rounded-lg border border-border hover:border-primary hover:bg-primary-50 disabled:opacity-50"
          >
            {opt}
          </button>
        ))}
      </div>
      {feedback && <p className="text-sm font-medium text-primary">{feedback}</p>}
      {done && (
        <p className="text-success-700 font-medium">
          {payload.reward_item || 'Victory!'}
        </p>
      )}
    </div>
  );
};

export default RpgBossBattle;
