import React from 'react';
import Icon from 'components/AppIcon';
import InteractiveQuiz from '../../interactive-learning-session/components/InteractiveQuiz';
import GameRenderer from '../../../components/games/GameRenderer';

const CanvasSurface = ({ surface, uiAdaptations, onGameComplete, onQuizAnswer, disabled }) => {
  if (!surface) return null;

  switch (surface.type) {
    case 'message':
      return (
        <div className="prose prose-sm max-w-none text-text-primary whitespace-pre-wrap">
          {surface.message}
        </div>
      );

    case 'lesson_snippet':
      return (
        <div className="space-y-3">
          <h3 className="font-heading font-semibold text-lg text-text-primary">{surface.title}</h3>
          <p className="text-text-primary leading-relaxed whitespace-pre-wrap">{surface.content}</p>
          {surface.keyTakeaways?.length > 0 && (
            <ul className="text-sm text-text-secondary space-y-1 list-disc list-inside">
              {surface.keyTakeaways.map((t) => (
                <li key={t}>{t}</li>
              ))}
            </ul>
          )}
        </div>
      );

    case 'game':
      return (
        <div
          className={disabled ? 'pointer-events-none opacity-50 select-none' : undefined}
          aria-disabled={disabled || undefined}
        >
          <GameRenderer
            game={surface.game}
            uiAdaptations={uiAdaptations}
            onComplete={disabled ? undefined : onGameComplete}
            disabled={disabled}
          />
        </div>
      );

    case 'quiz':
      return (
        <div
          className={disabled ? 'pointer-events-none opacity-50 select-none' : undefined}
          aria-disabled={disabled || undefined}
        >
          <InteractiveQuiz
            quiz={surface.quiz}
            uiAdaptations={uiAdaptations}
            onAnswer={disabled ? undefined : onQuizAnswer}
          />
        </div>
      );

    case 'follow_up_prompt':
      return (
        <div className="flex items-start gap-3 p-4 bg-primary-50 border border-primary-100 rounded-lg">
          <Icon name="MessageCircle" size={20} className="text-primary mt-0.5 shrink-0" />
          <p className="text-text-primary font-medium">{surface.prompt}</p>
        </div>
      );

    default:
      return null;
  }
};

export default CanvasSurface;
