import React, { useState } from 'react';

const InvestigationNoir = ({ payload, onComplete, disabled }) => {
  const questions = payload?.interrogation_questions || [];
  const [qIdx, setQIdx] = useState(0);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);
  const [note, setNote] = useState(null);

  const q = questions[qIdx];

  const pick = (responseIndex) => {
    if (disabled || done || !q) return;
    const exposedLie = responseIndex === q.telltale_lie_index;
    const nextScore = score + (exposedLie ? 1 : 0);
    setScore(nextScore);
    setNote(exposedLie ? 'Lie exposed — solid detective work.' : 'That line checked out.');

    if (qIdx >= questions.length - 1) {
      setDone(true);
      const guilty = (payload.suspects || []).find((s) => s.is_guilty);
      const pct = Math.min(100, Math.round((nextScore / Math.max(questions.length, 1)) * 100));
      onComplete?.({
        score: guilty && nextScore >= questions.length - 1 ? Math.max(pct, 85) : pct,
        gameType: payload?.style_id,
      });
    } else {
      setTimeout(() => {
        setQIdx((i) => i + 1);
        setNote(null);
      }, 700);
    }
  };

  if (!q) {
    return <p className="text-sm text-text-secondary">Case file incomplete.</p>;
  }

  return (
    <div className="space-y-4 bg-slate-950 text-slate-100 p-4 rounded-lg">
      <p className="font-serif text-lg">{payload.case_name}</p>
      <p className="text-sm text-slate-400">{payload.crime_scene_notes}</p>
      <ul className="text-xs space-y-1">
        {(payload.suspects || []).map((s) => (
          <li key={s.name}>
            <strong>{s.name}</strong> — {s.alibi_clue}
          </li>
        ))}
      </ul>
      <p className="text-sm italic">{q.line_of_questioning}</p>
      <p className="text-xs text-slate-500">Interrogating: {q.target_suspect}</p>
      <div className="grid gap-2">
        {(q.responses || []).map((r, i) => (
          <button
            key={r}
            type="button"
            disabled={disabled || done}
            onClick={() => pick(i)}
            className="text-left px-3 py-2 border border-slate-700 rounded hover:border-amber-600 disabled:opacity-50"
          >
            “{r}”
          </button>
        ))}
      </div>
      {note && <p className="text-amber-400 text-sm">{note}</p>}
      {done && <p className="text-green-400">Case closed.</p>}
    </div>
  );
};

export default InvestigationNoir;
