import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import api from '../lib/api';

const STORAGE_KEY = 'adaptivelearn_locale';

export const I18nContext = createContext(null);

const FALLBACK = {
  nav: { catalog: 'Catalog', flashcards: 'Flashcards', planner: 'Planner', goals: 'Goals', rankings: 'Rankings', notes: 'Notes', admin: 'Admin' },
  common: { loading: 'Loading...', save: 'Save', cancel: 'Cancel' },
};

export const I18nProvider = ({ children }) => {
  const [locale, setLocaleState] = useState(() => localStorage.getItem(STORAGE_KEY) || 'en');
  const [strings, setStrings] = useState(FALLBACK);
  const [loading, setLoading] = useState(true);

  const loadLocale = useCallback(async (lang) => {
    try {
      const data = await api.getTranslations(lang);
      setStrings(data);
    } catch {
      if (lang !== 'en') {
        const en = await api.getTranslations('en').catch(() => FALLBACK);
        setStrings(en);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadLocale(locale);
  }, [locale, loadLocale]);

  const setLocale = (lang) => {
    localStorage.setItem(STORAGE_KEY, lang);
    setLocaleState(lang);
    setLoading(true);
  };

  const t = (path, fallback = '') => {
    const keys = path.split('.');
    let cur = strings;
    for (const k of keys) {
      cur = cur?.[k];
      if (cur === undefined) return fallback || path;
    }
    return typeof cur === 'string' ? cur : fallback || path;
  };

  return (
    <I18nContext.Provider value={{ locale, setLocale, t, strings, loading }}>
      {children}
    </I18nContext.Provider>
  );
};

export function useI18n() {
  return useContext(I18nContext) || { locale: 'en', setLocale: () => {}, t: (p) => p, loading: false };
}
