import React, { useState, useEffect, useMemo } from 'react';
import Icon from 'components/AppIcon';
import GameRenderer from 'components/games/GameRenderer';

const LiveInteractiveGame = ({ game, uiAdaptations, onComplete, onAbandon }) => {
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);
  const [timeLeft, setTimeLeft] = useState(game?.timeLimitSeconds || 90);
  const [feedback, setFeedback] = useState(null);

  // Match pairs state
  const [selectedLeft, setSelectedLeft] = useState(null);
  const [matchedPairs, setMatchedPairs] = useState(new Set());
  const [wrongPair, setWrongPair] = useState(null);

  // Ordering state
  const [orderItems, setOrderItems] = useState([]);

  // Fill blank state
  const [blankAnswers, setBlankAnswers] = useState({});

  // Scenario / quiz state
  const [selectedChoice, setSelectedChoice] = useState(null);
  const [quizIndex, setQuizIndex] = useState(0);
  const [quizScore, setQuizScore] = useState(0);

  useEffect(() => {
    if (game?.gameType === 'ordering' && game.payload?.items?.length) {
      setOrderItems([...game.payload.items].sort(() => Math.random() - 0.5));
    }
    setScore(0);
    setFinished(false);
    setTimeLeft(game?.timeLimitSeconds || 90);
    setFeedback(null);
    setMatchedPairs(new Set());
    setBlankAnswers({});
    setSelectedChoice(null);
    setQuizIndex(0);
    setQuizScore(0);
  }, [game?.id]);

  useEffect(() => {
    if (finished || !game) return;
    const timer = setInterval(() => {
      setTimeLeft((t) => {
        if (t <= 1) {
          clearInterval(timer);
          handleFinish(Math.round((score / (game.points || 100)) * 100));
          return 0;
        }
        return t - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [finished, game, score]);

  const handleFinish = (finalScore) => {
    if (finished) return;
    setFinished(true);
    onComplete?.({
      score: finalScore,
      gameType: game.gameType,
      timeSpent: (game.timeLimitSeconds || 90) - timeLeft,
    });
  };

  const accent = uiAdaptations?.accentColor || '#4F46E5';

  const pairs = game?.payload?.pairs || [];
  const leftItems = useMemo(
    () => pairs.map((p, i) => ({ id: i, text: p.left })),
    [game?.id, pairs.length]
  );
  const rightItems = useMemo(
    () => [...pairs.map((p, i) => ({ id: i, text: p.right }))].sort(() => Math.random() - 0.5),
    [game?.id]
  );

  if (!game) {
    return (
      <div className="text-center py-12 text-text-secondary">
        <Icon name="Gamepad2" size={32} className="mx-auto mb-3 opacity-50" />
        <p>Loading interactive game...</p>
      </div>
    );
  }

  if (game.engine === 'styled' || game.style_id || game.payload?.style_id) {
    return (
      <GameRenderer
        game={game}
        uiAdaptations={uiAdaptations}
        onComplete={onComplete}
        onAbandon={onAbandon}
      />
    );
  }

  const renderMatchPairs = () => {
    const tryMatch = (rightId) => {
      if (selectedLeft === null || matchedPairs.has(selectedLeft)) return;
      if (selectedLeft === rightId) {
        const next = new Set(matchedPairs);
        next.add(selectedLeft);
        setMatchedPairs(next);
        setSelectedLeft(null);
        const newScore = score + Math.round((game.points || 100) / pairs.length);
        setScore(newScore);
        if (next.size === pairs.length) {
          setFeedback(game.completionMessage);
          setTimeout(() => handleFinish(100), 800);
        }
      } else {
        setWrongPair(rightId);
        setTimeout(() => setWrongPair(null), 600);
        setSelectedLeft(null);
      }
    };

    return (
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          {leftItems.map((item) => (
            <button
              key={`l-${item.id}`}
              type="button"
              disabled={matchedPairs.has(item.id)}
              onClick={() => setSelectedLeft(item.id)}
              className={`w-full p-3 rounded-lg border-2 text-left text-sm transition-all ${
                matchedPairs.has(item.id)
                  ? 'border-success bg-success-50 opacity-60'
                  : selectedLeft === item.id
                    ? 'border-primary bg-primary-50'
                    : 'border-border bg-surface hover:bg-surface-50'
              }`}
            >
              {item.text}
            </button>
          ))}
        </div>
        <div className="space-y-2">
          {rightItems.map((item) => (
            <button
              key={`r-${item.id}`}
              type="button"
              disabled={matchedPairs.has(item.id)}
              onClick={() => tryMatch(item.id)}
              className={`w-full p-3 rounded-lg border-2 text-left text-sm transition-all ${
                matchedPairs.has(item.id)
                  ? 'border-success bg-success-50 opacity-60'
                  : wrongPair === item.id
                    ? 'border-error bg-error-50'
                    : 'border-border bg-surface hover:bg-surface-50'
              }`}
            >
              {item.text}
            </button>
          ))}
        </div>
      </div>
    );
  };

  const renderOrdering = () => {
    const correctOrder = game.payload.correctOrder || game.payload.items?.map((_, i) => i) || [];

    const moveItem = (from, to) => {
      if (from === to) return;
      const next = [...orderItems];
      const [moved] = next.splice(from, 1);
      next.splice(to, 0, moved);
      setOrderItems(next);
    };

    const checkOrder = () => {
      const original = game.payload.items || [];
      const userOrder = orderItems.map((item) => original.indexOf(item));
      const correct = userOrder.every((val, idx) => val === correctOrder[idx]);
      if (correct) {
        setFeedback(game.completionMessage);
        handleFinish(100);
      } else {
        setFeedback('Not quite — try rearranging the steps.');
        setScore(Math.max(0, score - 10));
      }
    };

    return (
      <div className="space-y-2">
        {orderItems.map((item, index) => (
          <div key={item} className="flex items-center gap-2">
            <span className="text-xs text-text-secondary w-6">{index + 1}.</span>
            <div className="flex-1 p-3 rounded-lg border border-border bg-surface text-sm">{item}</div>
            <button type="button" onClick={() => moveItem(index, Math.max(0, index - 1))} className="p-1 text-text-secondary hover:text-primary">
              <Icon name="ChevronUp" size={16} />
            </button>
            <button type="button" onClick={() => moveItem(index, Math.min(orderItems.length - 1, index + 1))} className="p-1 text-text-secondary hover:text-primary">
              <Icon name="ChevronDown" size={16} />
            </button>
          </div>
        ))}
        <button type="button" onClick={checkOrder} className="w-full btn btn-primary py-2 mt-4">
          Check Order
        </button>
      </div>
    );
  };

  const renderFillBlank = () => {
    const segments = game.payload.segments || [];
    let blankIdx = 0;

    const checkBlanks = () => {
      let correct = 0;
      let total = 0;
      segments.forEach((seg) => {
        if (seg.type === 'blank') {
          total++;
          const ans = (blankAnswers[blankIdx] || '').trim().toLowerCase();
          const expected = (seg.answer || '').trim().toLowerCase();
          if (ans === expected) correct++;
          blankIdx++;
        }
      });
      blankIdx = 0;
      const pct = total ? Math.round((correct / total) * 100) : 0;
      if (pct >= 80) {
        setFeedback(game.completionMessage);
        handleFinish(pct);
      } else {
        setFeedback(`Got ${correct}/${total} correct. ${segHint(segments)}`);
      }
    };

    blankIdx = 0;
    return (
      <div>
        <p className="text-base leading-relaxed mb-4 flex flex-wrap gap-1 items-center">
          {segments.map((seg, i) => {
            if (seg.type === 'blank') {
              const idx = blankIdx++;
              return (
                <input
                  key={i}
                  type="text"
                  value={blankAnswers[idx] || ''}
                  onChange={(e) => setBlankAnswers((prev) => ({ ...prev, [idx]: e.target.value }))}
                  placeholder={seg.hint || '...'}
                  className="inline-block w-32 px-2 py-1 border-b-2 border-primary bg-transparent text-center focus:outline-none"
                />
              );
            }
            return <span key={i}>{seg.value}</span>;
          })}
        </p>
        <button type="button" onClick={checkBlanks} className="btn btn-primary px-6 py-2">
          Check Answers
        </button>
      </div>
    );
  };

  const renderScenario = () => {
    const { prompt, choices = [] } = game.payload;
    const pick = (index) => {
      setSelectedChoice(index);
      const choice = choices[index];
      setFeedback(choice.feedback || choice.outcome);
      const pct = choice.isOptimal ? 100 : 50;
      setTimeout(() => handleFinish(pct), 1200);
    };

    return (
      <div>
        <p className="text-base mb-4 p-4 bg-surface-50 rounded-lg border border-border">{prompt}</p>
        <div className="space-y-2">
          {choices.map((c, i) => (
            <button
              key={c.label}
              type="button"
              disabled={selectedChoice !== null}
              onClick={() => pick(i)}
              className={`w-full p-4 text-left rounded-lg border-2 transition-all ${
                selectedChoice === i
                  ? c.isOptimal
                    ? 'border-success bg-success-50'
                    : 'border-warning bg-warning-50'
                  : 'border-border hover:border-primary hover:bg-primary-50'
              }`}
            >
              {c.label}
            </button>
          ))}
        </div>
      </div>
    );
  };

  const renderRapidQuiz = () => {
    const questions = game.payload.questions || [];
    const q = questions[quizIndex];
    if (!q) return null;

    const submit = (optionIndex) => {
      const correct = optionIndex === q.correct;
      const nextScore = quizScore + (correct ? 1 : 0);
      setQuizScore(nextScore);
      setFeedback(q.explanation);

      setTimeout(() => {
        if (quizIndex + 1 < questions.length) {
          setQuizIndex(quizIndex + 1);
          setFeedback(null);
        } else {
          const pct = Math.round((nextScore / questions.length) * 100);
          handleFinish(pct);
        }
      }, 1500);
    };

    return (
      <div>
        <p className="text-sm text-text-secondary mb-2">
          Question {quizIndex + 1} of {questions.length}
        </p>
        <p className="font-medium mb-4">{q.question}</p>
        <div className="space-y-2">
          {q.options.map((opt, i) => (
            <button
              key={opt}
              type="button"
              onClick={() => submit(i)}
              disabled={!!feedback}
              className="w-full p-3 text-left rounded-lg border border-border hover:border-primary hover:bg-primary-50 disabled:opacity-70"
            >
              {opt}
            </button>
          ))}
        </div>
      </div>
    );
  };

  const renderGame = () => {
    switch (game.gameType) {
      case 'match_pairs':
        return renderMatchPairs();
      case 'ordering':
        return renderOrdering();
      case 'fill_blank':
        return renderFillBlank();
      case 'scenario':
        return renderScenario();
      case 'rapid_quiz':
      default:
        return renderRapidQuiz();
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-lg" style={{ backgroundColor: `${accent}20` }}>
            <Icon name="Gamepad2" size={20} style={{ color: accent }} />
          </div>
          <div>
            <h2 className="font-heading font-bold text-lg text-text-primary">{game.title}</h2>
            <p className="text-sm text-text-secondary capitalize">{game.gameType.replace(/_/g, ' ')}</p>
          </div>
        </div>
        <div className="text-right">
          <div className="text-sm font-mono font-medium">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</div>
          <div className="text-xs text-text-secondary">Score: {Math.min(score, game.points)}</div>
        </div>
      </div>

      <p className="text-sm text-text-secondary bg-surface-50 p-3 rounded-lg border border-border">
        {game.instructions}
      </p>

      {!finished && renderGame()}

      {feedback && (
        <div className={`p-4 rounded-lg border ${finished ? 'border-success bg-success-50 text-success-700' : 'border-primary bg-primary-50 text-primary-700'}`}>
          {feedback}
        </div>
      )}

      {!finished && onAbandon && (
        <button type="button" onClick={onAbandon} className="text-sm text-text-secondary hover:text-text-primary">
          Skip game →
        </button>
      )}
    </div>
  );
};

function segHint(segments) {
  const blank = segments.find((s) => s.type === 'blank');
  return blank?.hint ? `Hint: ${blank.hint}` : 'Review the lesson above.';
}

export default LiveInteractiveGame;
