import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { UserContext } from './UserContext';
import api from '../lib/api';

export const FlashcardContext = createContext(null);

export const FlashcardProvider = ({ children }) => {
  const { currentUser } = useContext(UserContext);
  const [cards, setCards] = useState([]);
  const [dueCards, setDueCards] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refresh = useCallback(async () => {
    if (!currentUser?.uid) return;
    try {
      setLoading(true);
      setError(null);
      const [all, due, cardStats] = await Promise.all([
        api.getFlashcards(),
        api.getDueFlashcards(),
        api.getFlashcardStats(),
      ]);
      setCards(all);
      setDueCards(due);
      setStats(cardStats);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [currentUser?.uid]);

  const reviewCard = async (cardId, quality) => {
    const updated = await api.reviewFlashcard(cardId, quality);
    setCards((prev) => prev.map((c) => (c.id === cardId ? updated : c)));
    setDueCards((prev) => prev.filter((c) => c.id !== cardId));
    await refresh();
    return updated;
  };

  const createCard = async (payload) => {
    const card = await api.createFlashcard(payload);
    await refresh();
    return card;
  };

  const seedDeck = async () => {
    const result = await api.seedFlashcards();
    await refresh();
    return result;
  };

  useEffect(() => {
    refresh();
  }, [refresh]);

  return (
    <FlashcardContext.Provider
      value={{ cards, dueCards, stats, loading, error, refresh, reviewCard, createCard, seedDeck }}
    >
      {children}
    </FlashcardContext.Provider>
  );
};

export function useFlashcards() {
  return useContext(FlashcardContext) || {};
}
