import React, { useMemo, useState } from 'react';

/** Fallback: extract MCQ-like steps from any styled payload */
function extractQuestions(payload) {
  const qs = [];

  if (payload?.phases) {
    for (const p of payload.phases) {
      qs.push({
        question: p.challenge_question,
        options: p.options,
        correct: p.correct_index,
      });
    }
  }
  if (payload?.nodes) {
    for (const n of payload.nodes) {
      qs.push({
        question: n.decryption_riddle,
        options: n.key_phrases,
        correct: n.correct_phrase_index,
      });
    }
  }
  if (payload?.rooms) {
    for (const r of payload.rooms) {
      qs.push({
        question: `Which door is correct in ${r.room_name}?`,
        options: [r.door_left_inscription, r.door_right_inscription],
        correct: r.correct_door === 'left' ? 0 : 1,
      });
    }
  }
  if (payload?.asteroids) {
    for (const a of payload.asteroids) {
      qs.push({
        question: a.extraction_math_puzzle,
        options: a.numeric_answers?.map(String),
        correct: a.correct_index,
      });
    }
  }
  if (payload?.historical_anchors) {
    for (const h of payload.historical_anchors) {
      qs.push({
        question: h.broken_event,
        options: h.correction_options,
        correct: h.butterfly_effect_index,
      });
    }
  }
  if (payload?.matchups) {
    for (const m of payload.matchups) {
      qs.push({
        question: m.strategic_reasoning_clue || `Counter ${m.enemy_card_played}`,
        options: [m.winning_counter_card_name, 'Wrong card A', 'Wrong card B'],
        correct: 0,
      });
    }
  }

  return qs.filter((q) => q.question && q.options?.length);
}

const GenericStyledQuiz = ({ title, payload, styleId, onComplete, disabled }) => {
  const questions = useMemo(() => extractQuestions(payload), [payload]);
  const [idx, setIdx] = useState(0);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);

  const q = questions[idx];

  const pick = (i) => {
    if (disabled || done || !q) return;
    const correct = i === q.correct;
    const nextScore = score + (correct ? 1 : 0);
    setScore(nextScore);
    if (idx >= questions.length - 1) {
      setDone(true);
      const pct = Math.round((nextScore / questions.length) * 100);
      onComplete?.({ score: pct, gameType: styleId || payload?.style_id });
    } else {
      setIdx((n) => n + 1);
    }
  };

  if (!questions.length) {
    return (
      <p className="text-sm text-text-secondary">
        {title || 'Game'} — interactive shell loading fallback unavailable. Try regenerating.
      </p>
    );
  }

  return (
    <div className="space-y-3">
      {styleId && (
        <p className="text-xs uppercase tracking-wide text-text-secondary">{styleId.replace(/_/g, ' ')}</p>
      )}
      <p className="font-medium">{q.question}</p>
      <div className="grid gap-2">
        {q.options.map((opt, i) => (
          <button
            key={`${idx}-${i}`}
            type="button"
            disabled={disabled || done}
            onClick={() => pick(i)}
            className="text-left px-4 py-2 rounded-lg border border-border hover:border-primary disabled:opacity-50"
          >
            {opt}
          </button>
        ))}
      </div>
      <p className="text-xs text-text-secondary">
        Question {idx + 1} / {questions.length}
      </p>
    </div>
  );
};

export default GenericStyledQuiz;
