import React, { Suspense, lazy } from "react";
import { BrowserRouter, Routes as RouterRoutes, Route } from "react-router-dom";
import ScrollToTop from "components/ScrollToTop";
import ErrorBoundary from "components/ErrorBoundary";
import Header from "components/ui/Header";
import AdaptiveProgressIndicator from "components/ui/AdaptiveProgressIndicator";
import SessionControlPanel from "components/ui/SessionControlPanel";
import DynamicContextMenu from "components/ui/DynamicContextMenu";
import LoadingState from "components/ui/LoadingState";
import RequireAuth from "components/RequireAuth";
import RequireAdmin from "components/RequireAdmin";
import Footer from "components/ui/Footer";

// Eager-load primary entry points
import LearnCanvas from "pages/learn-canvas";
import LoginPage from "pages/Login";
import PrivacyPage from "pages/legal/PrivacyPage";
import TermsPage from "pages/legal/TermsPage";

// Lazy-load secondary routes (charts, admin, heavy dashboards)
const AdaptiveLearningDashboard = lazy(() => import("pages/adaptive-learning-dashboard"));
const InteractiveLearningSession = lazy(() => import("pages/interactive-learning-session"));
const ProgressAnalyticsDashboard = lazy(() => import("pages/progress-analytics-dashboard"));
const UserProfileSettings = lazy(() => import("pages/user-profile-settings"));
const SearchResults = lazy(() => import("pages/SearchResults"));
const FlashcardsPage = lazy(() => import("pages/flashcards"));
const CourseCatalog = lazy(() => import("pages/course-catalog"));
const StudyPlannerPage = lazy(() => import("pages/study-planner"));
const GoalsPage = lazy(() => import("pages/goals"));
const LeaderboardPage = lazy(() => import("pages/leaderboard"));
const AdminConsole = lazy(() => import("pages/admin"));
const ResetPasswordPage = lazy(() => import("pages/ResetPasswordPage"));
const NotFound = lazy(() => import("pages/NotFound"));

const PageLoader = () => <LoadingState message="Loading page..." fullScreen={false} />;

const Routes = () => {
  return (
    <BrowserRouter>
      <ErrorBoundary>
        <ScrollToTop />
        <div className="min-h-screen bg-background flex flex-col">
          <Header />
          <AdaptiveProgressIndicator />
          <SessionControlPanel />
          <DynamicContextMenu />
          <main className="pt-16 flex-1">
            <Suspense fallback={<PageLoader />}>
              <RouterRoutes>
                <Route path="/login" element={<LoginPage />} />
                <Route path="/reset-password" element={<ResetPasswordPage />} />
                <Route path="/privacy" element={<PrivacyPage />} />
                <Route path="/terms" element={<TermsPage />} />
                <Route path="/" element={
                  <RequireAuth>
                    <LearnCanvas />
                  </RequireAuth>
                } />
                <Route path="/learn" element={
                  <RequireAuth>
                    <LearnCanvas />
                  </RequireAuth>
                } />
                <Route path="/adaptive-learning-dashboard" element={
                  <RequireAuth>
                    <AdaptiveLearningDashboard />
                  </RequireAuth>
                } />
                <Route path="/interactive-learning-session/:nodeId" element={
                  <RequireAuth>
                    <InteractiveLearningSession />
                  </RequireAuth>
                } />
                <Route path="/interactive-learning-session" element={
                  <RequireAuth>
                    <InteractiveLearningSession />
                  </RequireAuth>
                } />
                <Route path="/progress-analytics-dashboard" element={
                  <RequireAuth>
                    <ProgressAnalyticsDashboard />
                  </RequireAuth>
                } />
                <Route path="/user-profile-settings" element={
                  <RequireAuth>
                    <UserProfileSettings />
                  </RequireAuth>
                } />
                <Route path="/search" element={
                  <RequireAuth>
                    <SearchResults />
                  </RequireAuth>
                } />
                <Route path="/flashcards" element={
                  <RequireAuth>
                    <FlashcardsPage />
                  </RequireAuth>
                } />
                <Route path="/course-catalog" element={
                  <RequireAuth>
                    <CourseCatalog />
                  </RequireAuth>
                } />
                <Route path="/study-planner" element={
                  <RequireAuth>
                    <StudyPlannerPage />
                  </RequireAuth>
                } />
                <Route path="/goals" element={
                  <RequireAuth>
                    <GoalsPage />
                  </RequireAuth>
                } />
                <Route path="/leaderboard" element={
                  <RequireAuth>
                    <LeaderboardPage />
                  </RequireAuth>
                } />
                <Route path="/admin" element={
                  <RequireAuth>
                    <RequireAdmin>
                      <AdminConsole />
                    </RequireAdmin>
                  </RequireAuth>
                } />
                <Route path="*" element={<NotFound />} />
              </RouterRoutes>
            </Suspense>
          </main>
          <Footer />
        </div>
      </ErrorBoundary>
    </BrowserRouter>
  );
};

export default Routes;
