import React, { useState } from 'react';

const CyberTerminal = ({ payload, onComplete, disabled }) => {
  const nodes = payload?.nodes || [];
  const [nodeIdx, setNodeIdx] = useState(0);
  const [done, setDone] = useState(false);
  const [msg, setMsg] = useState(null);

  const node = nodes[nodeIdx];

  const pick = (index) => {
    if (disabled || done || !node) return;
    if (index === node.correct_phrase_index) {
      if (nodeIdx >= nodes.length - 1) {
        setDone(true);
        setMsg('System decrypted.');
        onComplete?.({ score: 92, gameType: payload?.style_id });
      } else {
        setMsg('Node unlocked…');
        setTimeout(() => {
          setNodeIdx((i) => i + 1);
          setMsg(null);
        }, 600);
      }
    } else {
      setMsg('Decryption failed — trace corrupted.');
    }
  };

  if (!node) {
    return <p className="text-sm text-text-secondary">Terminal data incomplete.</p>;
  }

  return (
    <div className="font-mono text-sm space-y-3 bg-slate-900 text-green-400 p-4 rounded-lg">
      <p className="text-green-300">[{payload.security_level}] {payload.game_title}</p>
      <p className="text-slate-400">{payload.system_description}</p>
      <p className="text-yellow-300">{node.encrypted_log_snippet}</p>
      <p className="text-white">{node.decryption_riddle}</p>
      <div className="space-y-2">
        {(node.key_phrases || []).map((phrase, i) => (
          <button
            key={phrase}
            type="button"
            disabled={disabled || done}
            onClick={() => pick(i)}
            className="block w-full text-left px-3 py-2 border border-green-800 hover:bg-green-950 disabled:opacity-50"
          >
            &gt; {phrase}
          </button>
        ))}
      </div>
      {msg && <p className="text-green-200">{msg}</p>}
    </div>
  );
};

export default CyberTerminal;
