import React, { createContext, useState, useEffect, useContext } from 'react';
import { UserContext } from './UserContext';
import api from '../lib/api';

export const DataContext = createContext(null);

export const DataProvider = ({ children }) => {
  const { currentUser } = useContext(UserContext);
  const [userStats, setUserStats] = useState(null);
  const [achievements, setAchievements] = useState([]);
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const loadUserData = async () => {
    if (!currentUser?.uid) {
      setUserStats(null);
      setAchievements([]);
      setAnalytics(null);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const [stats, achievementList, analyticsData] = await Promise.all([
        api.getStats(),
        api.getAchievements(),
        api.getAnalytics(),
      ]);

      setUserStats(stats);
      setAchievements(achievementList);
      setAnalytics(analyticsData);
    } catch (err) {
      console.error('Error loading dashboard data:', err);
      setError(err.message || 'Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  const updateUserStats = async (newStats) => {
    const updatedStats = { ...userStats, ...newStats, lastUpdated: new Date().toISOString() };
    setUserStats(updatedStats);

    if (!currentUser?.uid) return;

    try {
      const saved = await api.updateStats(updatedStats);
      setUserStats(saved);
    } catch (err) {
      console.error('Error updating stats:', err);
      setError(err.message || 'Failed to save stats');
    }
  };

  const addAchievement = async (achievement) => {
    if (!currentUser?.uid) return;

    try {
      const saved = await api.addAchievement(achievement);
      setAchievements((prev) => [...prev, saved]);
    } catch (err) {
      console.error('Error adding achievement:', err);
      setError(err.message || 'Failed to save achievement');
    }
  };

  useEffect(() => {
    loadUserData();
  }, [currentUser?.uid]);

  const value = {
    userStats,
    achievements,
    analytics,
    loading,
    error,
    updateUserStats,
    addAchievement,
    refreshData: loadUserData,
  };

  return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
};
