import React from 'react';
import RpgBossBattle from './RpgBossBattle';
import CyberTerminal from './CyberTerminal';
import DungeonCrawler from './DungeonCrawler';
import AlchemyLab from './AlchemyLab';
import StrategySimulator from './StrategySimulator';
import InvestigationNoir from './InvestigationNoir';
import SpaceMining from './SpaceMining';
import RobotFactory from './RobotFactory';
import TimeTravelFixer from './TimeTravelFixer';
import CardBattler from './CardBattler';
import GenericStyledQuiz from './GenericStyledQuiz';

/**
 * Universal shell — routes styled JSON to specialized React mini-games.
 */
const StyledGameShell = ({ game, onComplete, disabled, uiAdaptations }) => {
  const payload = game?.payload || game;
  const styleId = payload?.style_id || game?.style_id;

  if (!styleId) {
    return (
      <GenericStyledQuiz
        title={game?.title}
        payload={payload}
        onComplete={onComplete}
        disabled={disabled}
      />
    );
  }

  const common = { payload, onComplete, disabled };

  switch (styleId) {
    case '001_RPG_BOSS_BATTLE':
      return <RpgBossBattle {...common} />;
    case '002_CYBER_TERMINAL_DECRYPTOR':
      return <CyberTerminal {...common} />;
    case '005_DUNGEON_CRAWLER_LOGIC':
      return <DungeonCrawler {...common} />;
    case '003_ALCHEMY_LAB_CRAFTER':
      return <AlchemyLab {...common} />;
    case '004_STRATEGY_RESOURCE_SIMULATOR':
      return <StrategySimulator {...common} />;
    case '006_INVESTIGATION_NOIR':
      return <InvestigationNoir {...common} />;
    case '007_SPACE_MINING_TYCOON':
      return <SpaceMining {...common} />;
    case '008_ROBOT_FACTORY_ASSEMBLER':
      return <RobotFactory {...common} />;
    case '009_TIME_TRAVEL_PARADOX_FIXER':
      return <TimeTravelFixer {...common} />;
    case '010_CARD_BATTLER_DECKBUILDER':
      return <CardBattler {...common} />;
    default:
      return (
        <GenericStyledQuiz
          title={game?.title || payload?.game_title || payload?.case_name}
          payload={payload}
          styleId={styleId}
          onComplete={onComplete}
          disabled={disabled}
          uiAdaptations={uiAdaptations}
        />
      );
  }
};

export default StyledGameShell;
