import React, { useState } from 'react';
import Icon from 'components/AppIcon';

const SessionFeedbackPanel = ({ onSubmit, disabled, coachMessage, uiAdaptations }) => {
  const [sentiment, setSentiment] = useState(3);
  const [difficulty, setDifficulty] = useState(3);
  const [comment, setComment] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const accent = uiAdaptations?.accentColor || '#4F46E5';

  const handleSubmit = () => {
    onSubmit?.({
      type: 'mid_session_feedback',
      sentiment,
      difficultyRating: difficulty,
      comment: comment.trim(),
      value: `sentiment=${sentiment}, difficulty=${difficulty}`,
    });
    setSubmitted(true);
    setTimeout(() => setSubmitted(false), 2000);
  };

  const RatingScale = ({ value, onChange, labels }) => (
    <div className="flex items-center gap-1">
      {[1, 2, 3, 4, 5].map((n) => (
        <button
          key={n}
          type="button"
          onClick={() => onChange(n)}
          className={`flex-1 py-1.5 rounded-full text-xs font-medium transition-all duration-200 ${
            value === n
              ? 'text-white shadow-sm scale-105'
              : 'bg-transparent text-text-secondary hover:bg-surface-100'
          }`}
          style={value === n ? { background: `linear-gradient(135deg, ${accent}, #EC4899)` } : {}}
        >
          {labels[n - 1]}
        </button>
      ))}
    </div>
  );

  return (
    <div className="rounded-xl bg-surface-50/60 backdrop-blur-sm p-4 space-y-3">
      {coachMessage && (
        <p className="text-xs text-primary-700 italic leading-relaxed">
          <Icon name="Brain" size={12} className="inline mr-1 align-middle" />
          {coachMessage}
        </p>
      )}

      <div className="space-y-3">
        <div>
          <span className="text-[11px] text-text-tertiary mb-1 block">Feeling</span>
          <RatingScale
            value={sentiment}
            onChange={setSentiment}
            labels={['😤', '😕', '😐', '🙂', '🤩']}
          />
        </div>

        <div>
          <span className="text-[11px] text-text-tertiary mb-1 block">Difficulty</span>
          <RatingScale
            value={difficulty}
            onChange={setDifficulty}
            labels={['Easy', '', 'OK', '', 'Hard']}
          />
        </div>

        <div className="flex gap-2">
          <input
            type="text"
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            placeholder="What's confusing?"
            className="flex-1 px-3 py-2 text-xs border border-border rounded-full bg-surface focus:outline-none focus:ring-1 focus:ring-primary"
          />
          <button
            type="button"
            onClick={handleSubmit}
            disabled={disabled || submitted}
            className="px-4 py-2 text-xs font-medium rounded-full text-white disabled:opacity-40 transition-all"
            style={{ background: `linear-gradient(135deg, ${accent}, #EC4899)` }}
          >
            {submitted ? 'Adapting...' : 'Send'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default SessionFeedbackPanel;
