import React, { useState } from 'react';

const AlchemyLab = ({ payload, onComplete, disabled }) => {
  const ingredients = payload?.available_ingredients || [];
  const env = payload?.environmental_controls || {};
  const [picked, setPicked] = useState([]);
  const [temp, setTemp] = useState('');
  const [msg, setMsg] = useState(null);
  const [done, setDone] = useState(false);

  const toggle = (name) => {
    if (disabled || done) return;
    setPicked((prev) =>
      prev.includes(name) ? prev.filter((n) => n !== name) : [...prev, name]
    );
  };

  const brew = () => {
    if (disabled || done) return;
    const correctParts = ingredients.filter((i) => i.is_correct_component).map((i) => i.name);
    const hasAll = correctParts.every((n) => picked.includes(n));
    const tempOk = !env.target_value || temp === env.target_value;

    if (hasAll && tempOk) {
      setDone(true);
      setMsg(`Success! ${payload.target_potion_name} brewed.`);
      onComplete?.({ score: 94, gameType: payload?.style_id });
    } else {
      setMsg(payload.failure_explosion_text || 'The mixture exploded! Re-read the recipe hint.');
    }
  };

  return (
    <div className="space-y-4">
      <p className="font-semibold">{payload.game_title}</p>
      <p className="text-sm text-text-secondary">{payload.recipe_hint}</p>
      <p className="text-sm">Target: <strong>{payload.target_potion_name}</strong></p>
      <div className="flex flex-wrap gap-2">
        {ingredients.map((ing) => (
          <button
            key={ing.name}
            type="button"
            disabled={disabled || done}
            onClick={() => toggle(ing.name)}
            className={`px-3 py-2 rounded-lg border text-sm ${
              picked.includes(ing.name) ? 'border-primary bg-primary-50' : 'border-border'
            }`}
          >
            {ing.name}
            <span className="block text-xs text-text-secondary">{ing.property}</span>
          </button>
        ))}
      </div>
      {env.variable_name && (
        <div>
          <label className="text-sm text-text-secondary">{env.variable_name}</label>
          <select
            value={temp}
            disabled={disabled || done}
            onChange={(e) => setTemp(e.target.value)}
            className="mt-1 w-full border border-border rounded-lg px-3 py-2"
          >
            <option value="">Select…</option>
            <option value={env.target_value}>{env.target_value}</option>
            {(env.wrong_values || []).map((v) => (
              <option key={v} value={v}>{v}</option>
            ))}
          </select>
        </div>
      )}
      <button
        type="button"
        disabled={disabled || done}
        onClick={brew}
        className="px-4 py-2 bg-primary text-white rounded-lg disabled:opacity-50"
      >
        Brew potion
      </button>
      {msg && <p className={`text-sm ${done ? 'text-success-700' : 'text-error'}`}>{msg}</p>}
    </div>
  );
};

export default AlchemyLab;
