import React, { useState } from 'react';

const StrategySimulator = ({ payload, onComplete, disabled }) => {
  const dilemmas = payload?.dilemmas || [];
  const [turn, setTurn] = useState(0);
  const [metrics, setMetrics] = useState({ ...payload.starting_values });
  const [done, setDone] = useState(false);
  const [lastOutcome, setLastOutcome] = useState(null);

  const dilemma = dilemmas[turn];
  const keys = payload.resources || { metric_a: 'A', metric_b: 'B' };

  const choose = (choice) => {
    if (disabled || done || !choice) return;
    const aKey = 'metric_a_val';
    const bKey = 'metric_b_val';
    setLastOutcome(choice.narrative_outcome);

    setMetrics((m) => {
      const next = {
        [aKey]: (m[aKey] || 0) + (choice.metric_a_impact || 0),
        [bKey]: (m[bKey] || 0) + (choice.metric_b_impact || 0),
      };
      if (turn >= dilemmas.length - 1) {
        setDone(true);
        const score = Math.min(100, 50 + Math.round((next[aKey] + next[bKey]) / 4));
        setTimeout(() => onComplete?.({ score, gameType: payload?.style_id }), 0);
      } else {
        setTimeout(() => {
          setTurn((t) => t + 1);
          setLastOutcome(null);
        }, 800);
      }
      return next;
    });
  };

  if (!dilemma) {
    return <p className="text-sm text-text-secondary">Strategy sim data incomplete.</p>;
  }

  return (
    <div className="space-y-4">
      <p className="font-semibold">{payload.game_title} — {payload.faction_name}</p>
      <div className="flex gap-4 text-sm font-mono">
        <span>{keys.metric_a}: {metrics.metric_a_val}</span>
        <span>{keys.metric_b}: {metrics.metric_b_val}</span>
      </div>
      <p className="text-sm">{dilemma.situation_event}</p>
      <div className="grid gap-2">
        {(dilemma.choices || []).map((c) => (
          <button
            key={c.text}
            type="button"
            disabled={disabled || done}
            onClick={() => choose(c)}
            className="text-left px-4 py-3 border border-border rounded-lg hover:border-primary disabled:opacity-50"
          >
            {c.text}
          </button>
        ))}
      </div>
      {lastOutcome && <p className="text-sm italic text-primary-700">{lastOutcome}</p>}
      {done && <p className="text-success-700 font-medium">Faction stabilized.</p>}
    </div>
  );
};

export default StrategySimulator;
